export default [{"id":"1902","jozz":"14","page":"267","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"9","line_end":"9","aya_no":"1","aya_text":"أَتَىٰٓ أَمۡرُ ٱللَّهِ فَلَا تَسۡتَعۡجِلُوهُۚ سُبۡحَٰنَهُۥ وَتَعَٰلَىٰ عَمَّا يُشۡرِكُونَ","aya_text_emlaey":"أتى أمر الله فلا تستعجلوه سبحانه وتعالى عما يشركون","aya_tafseer":"[1] قَرُب قيام الساعة وقضاء الله بعذابكم -أيها الكفار- فلا تستعجلوا العذاب استهزاء بوعيد الرسول لكم. تنزَّه الله سبحانه وتعالى عن الشرك والشركاء."},{"id":"1903","jozz":"14","page":"267","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"10","line_end":"11","aya_no":"2","aya_text":"يُنَزِّلُ ٱلۡمَلَٰٓئِكَةَ بِٱلرُّوحِ مِنۡ أَمۡرِهِۦ عَلَىٰ مَن يَشَآءُ مِنۡ عِبَادِهِۦٓ أَنۡ أَنذِرُوٓاْ أَنَّهُۥ لَآ إِلَٰهَ إِلَّآ أَنَا۠ فَٱتَّقُونِ","aya_text_emlaey":"ينـزل الملائكة بالروح من أمره على من يشاء من عباده أن أنذروا أنه لا إله إلا أنا فاتقون","aya_tafseer":"[2] ينزِّل الله الملائكة بالوحي مِن أمره على مَن يشاء من عباده المرسلين: بأن خوِّفوا الناس من الشرك، وأنه لا معبود بحق إلا أنا، فاتقون بأداء فرائضي وإفرادي بالعبادة والإخلاص."},{"id":"1904","jozz":"14","page":"267","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"11","line_end":"12","aya_no":"3","aya_text":"خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ بِٱلۡحَقِّۚ تَعَٰلَىٰ عَمَّا يُشۡرِكُونَ","aya_text_emlaey":"خلق السموات والأرض بالحق تعالى عما يشركون","aya_tafseer":"[3] خلق الله السموات والأرض بالحق؛ ليستدِل بهما العباد على عظمة خالقهما، وأنه وحده المستحق للعبادة، تنزَّه -سبحانه- وتعاظم عن شركهم."},{"id":"1905","jozz":"14","page":"267","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"12","line_end":"13","aya_no":"4","aya_text":"خَلَقَ ٱلۡإِنسَٰنَ مِن نُّطۡفَةٖ فَإِذَا هُوَ خَصِيمٞ مُّبِينٞ","aya_text_emlaey":"خلق الإنسان من نطفة فإذا هو خصيم مبين","aya_tafseer":"[4] خَلَق الإنسان من ماء مهين فإذا به يَقْوى ويغترُّ، فيصبح شديد الخصومة والجدال لربه في إنكار البعث، وغير ذلك، كقوله: مَن يُحۡيِ ٱلۡعِظَٰمَ وَهِيَ رَمِيمٞ، ونسي الله الذي خلقه من العدم."},{"id":"1906","jozz":"14","page":"267","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"13","line_end":"14","aya_no":"5","aya_text":"وَٱلۡأَنۡعَٰمَ خَلَقَهَاۖ لَكُمۡ فِيهَا دِفۡءٞ وَمَنَٰفِعُ وَمِنۡهَا تَأۡكُلُونَ","aya_text_emlaey":"والأنعام خلقها لكم فيها دفء ومنافع ومنها تأكلون","aya_tafseer":"[5] والأنعامَ من الإبل والبقر والغنم خلقها الله لكم -أيها الناس- وجعل في أصوافها وأوبارها وأشعارها الدفء، ومنافع أُخر في ألبانها وجلودها وركوبها، ومنها ما تأكلون."},{"id":"1907","jozz":"14","page":"267","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"15","line_end":"15","aya_no":"6","aya_text":"وَلَكُمۡ فِيهَا جَمَالٌ حِينَ تُرِيحُونَ وَحِينَ تَسۡرَحُونَ","aya_text_emlaey":"ولكم فيها جمال حين تريحون وحين تسرحون","aya_tafseer":"[6] ولكم فيها زينة تُدْخل السرور عليكم عندما تَرُدُّونها إلى منازلها في المساء، وعندما تُخْرجونها للمرعى في الصباح."},{"id":"1908","jozz":"14","page":"268","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"1","line_end":"2","aya_no":"7","aya_text":"وَتَحۡمِلُ أَثۡقَالَكُمۡ إِلَىٰ بَلَدٖ لَّمۡ تَكُونُواْ بَٰلِغِيهِ إِلَّا بِشِقِّ ٱلۡأَنفُسِۚ إِنَّ رَبَّكُمۡ لَرَءُوفٞ رَّحِيمٞ","aya_text_emlaey":"وتحمل أثقالكم إلى بلد لم تكونوا بالغيه إلا بشق الأنفس إن ربكم لرءوف رحيم","aya_tafseer":"[7] وتحمل هذه الأنعام ما ثَقُل من أمتعتكم إلى بلد بعيد، لم تكونوا مستطيعين الوصول إليه إلا بجهد شديد من أنفسكم ومشقة عظيمة، إن ربكم ليرحمكم رحمة واسعة في عاجلكم وآجلكم؛ حيث سخَّر لكم ما تحتاجون إليه، فله الحمد وله الشكر."},{"id":"1909","jozz":"14","page":"268","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"2","line_end":"3","aya_no":"8","aya_text":"وَٱلۡخَيۡلَ وَٱلۡبِغَالَ وَٱلۡحَمِيرَ لِتَرۡكَبُوهَا وَزِينَةٗۚ وَيَخۡلُقُ مَا لَا تَعۡلَمُونَ","aya_text_emlaey":"والخيل والبغال والحمير لتركبوها وزينة ويخلق ما لا تعلمون","aya_tafseer":"[8] وخلق لكم الخيل والبغال والحمير؛ لكي تركبوها، ولتكون جَمالاً لكم ومنظراً حسناً، ويخلق لكم من وسائل الركوب وغيرها ما لا عِلْمَ لكم به؛ لتزدادوا إيماناً به وشكراً له."},{"id":"1910","jozz":"14","page":"268","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"4","line_end":"5","aya_no":"9","aya_text":"وَعَلَى ٱللَّهِ قَصۡدُ ٱلسَّبِيلِ وَمِنۡهَا جَآئِرٞۚ وَلَوۡ شَآءَ لَهَدَىٰكُمۡ أَجۡمَعِينَ","aya_text_emlaey":"وعلى الله قصد السبيل ومنها جائر ولو شاء لهداكم أجمعين","aya_tafseer":"[9] وعلى الله بيان الطريق المستقيم لِهدايتكم، وهو الإسلام، ومن الطرق ما هو مائل لا يُوصل إلى الهداية، وهو كل ما خالف الإسلام من الملل والنحل. ولو شاء الله هدايتكم لَهداكم جميعاً للإيمان."},{"id":"1911","jozz":"14","page":"268","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"5","line_end":"6","aya_no":"10","aya_text":"هُوَ ٱلَّذِيٓ أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءٗۖ لَّكُم مِّنۡهُ شَرَابٞ وَمِنۡهُ شَجَرٞ فِيهِ تُسِيمُونَ","aya_text_emlaey":"هو الذي أنـزل من السماء ماء لكم منه شراب ومنه شجر فيه تسيمون","aya_tafseer":"[10] هو الذي أنزل لكم من السحاب مطراً، فجعل لكم منه ماءً تشربونه، وأخرج لكم به شجراً تَرْعَوْن فيه دوابَّكم، ويعود عليكم دَرُّها وَنفْعُها."},{"id":"1912","jozz":"14","page":"268","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"6","line_end":"8","aya_no":"11","aya_text":"يُنۢبِتُ لَكُم بِهِ ٱلزَّرۡعَ وَٱلزَّيۡتُونَ وَٱلنَّخِيلَ وَٱلۡأَعۡنَٰبَ وَمِن كُلِّ ٱلثَّمَرَٰتِۚ إِنَّ فِي ذَٰلِكَ لَأٓيَةٗ لِّقَوۡمٖ يَتَفَكَّرُونَ","aya_text_emlaey":"ينبت لكم به الزرع والزيتون والنخيل والأعناب ومن كل الثمرات إن في ذلك لآية لقوم يتفكرون","aya_tafseer":"[11] يُخرج لكم من الأرض بهذا الماء الواحد الزروع المختلفة، ويُخرج به الزيتون والنخيل والأعناب، ويُخرج به كل أنواع الثمار والفواكه. إن في ذلك الإخراج لَدلالةً واضحة لقوم يتأملون، فيعتبرون."},{"id":"1913","jozz":"14","page":"268","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"9","line_end":"11","aya_no":"12","aya_text":"وَسَخَّرَ لَكُمُ ٱلَّيۡلَ وَٱلنَّهَارَ وَٱلشَّمۡسَ وَٱلۡقَمَرَۖ وَٱلنُّجُومُ مُسَخَّرَٰتُۢ بِأَمۡرِهِۦٓۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّقَوۡمٖ يَعۡقِلُونَ","aya_text_emlaey":"وسخر لكم اليل والنهار والشمس والقمر والنجوم مسخرات بأمره إن في ذلك لآيات لقوم يعقلون","aya_tafseer":"[12] وسَخَّر لكم الليل لراحتكم، والنهار لمعاشكم، وسَخَّر لكم الشمس ضياء، والقمر نوراً ولمعرفة السنين والحساب، وغير ذلك من المنافع، والنجومُ في السماء مذللاتٌ لكم بأمر الله لمعرفة الأوقات، ولمعرفة وقت نضج الثمار والزروع، والاهتداء بها في الظلمات. إن في ذلك التسخير لَدلائلَ واضحةً لقوم يعقلون عن الله حججه وبراهينه."},{"id":"1914","jozz":"14","page":"268","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"11","line_end":"12","aya_no":"13","aya_text":"وَمَا ذَرَأَ لَكُمۡ فِي ٱلۡأَرۡضِ مُخۡتَلِفًا أَلۡوَٰنُهُۥٓۚ إِنَّ فِي ذَٰلِكَ لَأٓيَةٗ لِّقَوۡمٖ يَذَّكَّرُونَ","aya_text_emlaey":"وما ذرأ لكم في الأرض مختلفا ألوانه إن في ذلك لآية لقوم يذكرون","aya_tafseer":"[13] وسَخَّر ما خلقه لكم في الأرض من الدوابِّ والثمار والمعادن، وغير ذلك مما تختلف ألوانه ومنافعه. إن في ذلك الخَلْق واختلاف الألوان والمنافع لَعبرةً لقوم يتعظون، ويعلمون أنَّ في تسخير هذه الأشياء علاماتٍ على وحدانية الله تعالى وإفراده بالعبادة."},{"id":"1915","jozz":"14","page":"268","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"13","line_end":"15","aya_no":"14","aya_text":"وَهُوَ ٱلَّذِي سَخَّرَ ٱلۡبَحۡرَ لِتَأۡكُلُواْ مِنۡهُ لَحۡمٗا طَرِيّٗا وَتَسۡتَخۡرِجُواْ مِنۡهُ حِلۡيَةٗ تَلۡبَسُونَهَاۖ وَتَرَى ٱلۡفُلۡكَ مَوَاخِرَ فِيهِ وَلِتَبۡتَغُواْ مِن فَضۡلِهِۦ وَلَعَلَّكُمۡ تَشۡكُرُونَ","aya_text_emlaey":"وهو الذي سخر البحر لتأكلوا منه لحما طريا وتستخرجوا منه حلية تلبسونها وترى الفلك مواخر فيه ولتبتغوا من فضله ولعلكم تشكرون","aya_tafseer":"[14] وهو الذي سَخَّر لكم البحر؛ لتأكلوا مما تصطادون من سمكه لحماً طريّاً، وتستخرجوا منه زينة تَلْبَسونها كاللؤلؤ والمَرْجان، وترى السفن العظيمة تشق وجه الماء تذهب وتجيء، وتركبونها؛ لتطلبوا رزق الله بالتجارة والربح فيها، ولعلكم تشكرون لله تعالى على عظيم إنعامه عليكم، فلا تعبدون غيره."},{"id":"1916","jozz":"14","page":"269","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"1","line_end":"2","aya_no":"15","aya_text":"وَأَلۡقَىٰ فِي ٱلۡأَرۡضِ رَوَٰسِيَ أَن تَمِيدَ بِكُمۡ وَأَنۡهَٰرٗا وَسُبُلٗا لَّعَلَّكُمۡ تَهۡتَدُونَ","aya_text_emlaey":"وألقى في الأرض رواسي أن تميد بكم وأنهارا وسبلا لعلكم تهتدون","aya_tafseer":"[15] وأرسى في الأرض جبالاً تثبتها حتى لا تميل بكم، وجعل فيها أنهاراً؛ لتشربوا منها، وجعل فيها طرقاً؛ لتهتدوا بها في الوصول إلى الأماكن التي تقصدونها."},{"id":"1917","jozz":"14","page":"269","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"2","line_end":"2","aya_no":"16","aya_text":"وَعَلَٰمَٰتٖۚ وَبِٱلنَّجۡمِ هُمۡ يَهۡتَدُونَ","aya_text_emlaey":"وعلامات وبالنجم هم يهتدون","aya_tafseer":"[16] وجعل في الأرض معالم تستدلُّون بها على الطرق نهاراً، كما جعل النجوم للاهتداء بها ليلاً."},{"id":"1918","jozz":"14","page":"269","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"3","line_end":"3","aya_no":"17","aya_text":"أَفَمَن يَخۡلُقُ كَمَن لَّا يَخۡلُقُۚ أَفَلَا تَذَكَّرُونَ","aya_text_emlaey":"أفمن يخلق كمن لا يخلق أفلا تذكرون","aya_tafseer":"[17] أتجعلون الله الذي يخلق كل هذه الأشياء وغيرها في استحقاق العبادة كالآلهة المزعومة التي لا تخلق شيئاً؟ أفلا تتذكرون عظمة الله، فتفردوه بالعبادة؟"},{"id":"1919","jozz":"14","page":"269","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"3","line_end":"4","aya_no":"18","aya_text":"وَإِن تَعُدُّواْ نِعۡمَةَ ٱللَّهِ لَا تُحۡصُوهَآۗ إِنَّ ٱللَّهَ لَغَفُورٞ رَّحِيمٞ","aya_text_emlaey":"وإن تعدوا نعمة الله لا تحصوها إن الله لغفور رحيم","aya_tafseer":"[18] وإن تحاولوا حَصْرَ نِعَم الله عليكم لا تَفُوا بحَصْرها؛ لكثرتها وتنوعها. إن الله لَغفور لكم رحيم بكم؛ إذ يتجاوز عن تقصيركم في أداء شكر النعم، ولا يقطعها عنكم لتفريطكم، ولا يعاجلكم بالعقوبة."},{"id":"1920","jozz":"14","page":"269","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"5","line_end":"5","aya_no":"19","aya_text":"وَٱللَّهُ يَعۡلَمُ مَا تُسِرُّونَ وَمَا تُعۡلِنُونَ","aya_text_emlaey":"والله يعلم ما تسرون وما تعلنون","aya_tafseer":"[19] والله سبحانه يعلم كل أعمالكم، سواء ما تخفونه منها في نفوسكم وما تظهرونه لغيركم، وسيجازيكم عليها."},{"id":"1921","jozz":"14","page":"269","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"5","line_end":"6","aya_no":"20","aya_text":"وَٱلَّذِينَ يَدۡعُونَ مِن دُونِ ٱللَّهِ لَا يَخۡلُقُونَ شَيۡـٔٗا وَهُمۡ يُخۡلَقُونَ","aya_text_emlaey":"والذين يدعون من دون الله لا يخلقون شيئا وهم يخلقون","aya_tafseer":"[20] والآلهة التي يعبدها المشركون لا تخلق شيئاً وإن صَغُر، فهي مخلوقات صنعها الكفار بأيديهم، فكيف يعبدونها؟"},{"id":"1922","jozz":"14","page":"269","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"6","line_end":"7","aya_no":"21","aya_text":"أَمۡوَٰتٌ غَيۡرُ أَحۡيَآءٖۖ وَمَا يَشۡعُرُونَ أَيَّانَ يُبۡعَثُونَ","aya_text_emlaey":"أموات غير أحياء وما يشعرون أيان يبعثون","aya_tafseer":"[21] هم جميعاً جمادات لا حياة فيها ولا تشعر بالوقت الذي يبعث الله فيه عابديها، وهي معهم ليُلقى بهم جميعاً في النار يوم القيامة."},{"id":"1923","jozz":"14","page":"269","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"7","line_end":"9","aya_no":"22","aya_text":"إِلَٰهُكُمۡ إِلَٰهٞ وَٰحِدٞۚ فَٱلَّذِينَ لَا يُؤۡمِنُونَ بِٱلۡأٓخِرَةِ قُلُوبُهُم مُّنكِرَةٞ وَهُم مُّسۡتَكۡبِرُونَ","aya_text_emlaey":"إلهكم إله واحد فالذين لا يؤمنون بالآخرة قلوبهم منكرة وهم مستكبرون","aya_tafseer":"[22] إلهكم المستحق وحده للعبادة هو الله الإله الواحد، فالذين لا يؤمنون بالبعث قلوبهم جاحدة وحدانيته سبحانه؛ لعدم خوفهم من عقابه، فهم متكبرون عن قبول الحق، وعبادة الله وحده."},{"id":"1924","jozz":"14","page":"269","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"9","line_end":"10","aya_no":"23","aya_text":"لَا جَرَمَ أَنَّ ٱللَّهَ يَعۡلَمُ مَا يُسِرُّونَ وَمَا يُعۡلِنُونَۚ إِنَّهُۥ لَا يُحِبُّ ٱلۡمُسۡتَكۡبِرِينَ","aya_text_emlaey":"لا جرم أن الله يعلم ما يسرون وما يعلنون إنه لا يحب المستكبرين","aya_tafseer":"[23] حقّاً أنَّ الله يعلم ما يخفونه مِن عقائد وأقوال وأفعال، وما يظهرونه منها، وسيجازيهم على ذلك، إنه عز وجل لا يحب المستكبرين عن عبادته والانقياد له، وسيجازيهم على ذلك."},{"id":"1925","jozz":"14","page":"269","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"10","line_end":"11","aya_no":"24","aya_text":"وَإِذَا قِيلَ لَهُم مَّاذَآ أَنزَلَ رَبُّكُمۡ قَالُوٓاْ أَسَٰطِيرُ ٱلۡأَوَّلِينَ","aya_text_emlaey":"وإذا قيل لهم ماذا أنـزل ربكم قالوا أساطير الأولين","aya_tafseer":"[24] وإذا سُئِل هؤلاء المشركون عَمَّا نزل على النبي محمد -صلى الله عليه وسلم- قالوا كذباً وزوراً: ما أتى إلا بقصص السابقين وأباطيلهم."},{"id":"1926","jozz":"14","page":"269","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"11","line_end":"13","aya_no":"25","aya_text":"لِيَحۡمِلُوٓاْ أَوۡزَارَهُمۡ كَامِلَةٗ يَوۡمَ ٱلۡقِيَٰمَةِ وَمِنۡ أَوۡزَارِ ٱلَّذِينَ يُضِلُّونَهُم بِغَيۡرِ عِلۡمٍۗ أَلَا سَآءَ مَا يَزِرُونَ","aya_text_emlaey":"ليحملوا أوزارهم كاملة يوم القيامة ومن أوزار الذين يضلونهم بغير علم ألا ساء ما يزرون","aya_tafseer":"[25] ستكون عاقبتهم أن يحملوا آثامهم كاملة يوم القيامة -لا يُغْفَر لهم منها شيء- ويَحْملوا من آثام الذين كذبوا عليهم؛ ليبعدوهم عن الإسلام من غير نقص من آثامهم. ألا قَبُحَ ما يحملونه من آثام."},{"id":"1927","jozz":"14","page":"269","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"13","line_end":"15","aya_no":"26","aya_text":"قَدۡ مَكَرَ ٱلَّذِينَ مِن قَبۡلِهِمۡ فَأَتَى ٱللَّهُ بُنۡيَٰنَهُم مِّنَ ٱلۡقَوَاعِدِ فَخَرَّ عَلَيۡهِمُ ٱلسَّقۡفُ مِن فَوۡقِهِمۡ وَأَتَىٰهُمُ ٱلۡعَذَابُ مِنۡ حَيۡثُ لَا يَشۡعُرُونَ","aya_text_emlaey":"قد مكر الذين من قبلهم فأتى الله بنيانهم من القواعد فخر عليهم السقف من فوقهم وأتاهم العذاب من حيث لا يشعرون","aya_tafseer":"[26] قد دبَّر الكفار مِن قَبْل هؤلاء المشركين المكايد لرسلهم، وما جاؤوا به من دعوة الحق، فأتى أمر الله بنيانهم من أساسه وقاعدته، فسقط عليهم السقف مِن فوقهم، وأتاهم الهلاك مِن مأمنهم، من حيث لا يحتسبون ولا يتوقعون أنه يأتيهم منه."},{"id":"1928","jozz":"14","page":"270","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"1","line_end":"3","aya_no":"27","aya_text":"ثُمَّ يَوۡمَ ٱلۡقِيَٰمَةِ يُخۡزِيهِمۡ وَيَقُولُ أَيۡنَ شُرَكَآءِيَ ٱلَّذِينَ كُنتُمۡ تُشَٰٓقُّونَ فِيهِمۡۚ قَالَ ٱلَّذِينَ أُوتُواْ ٱلۡعِلۡمَ إِنَّ ٱلۡخِزۡيَ ٱلۡيَوۡمَ وَٱلسُّوٓءَ عَلَى ٱلۡكَٰفِرِينَ","aya_text_emlaey":"ثم يوم القيامة يخزيهم ويقول أين شركائي الذين كنتم تشاقون فيهم قال الذين أوتوا العلم إن الخزي اليوم والسوء على الكافرين","aya_tafseer":"[27] ثم يوم القيامة يفضحهم الله بالعذاب ويذلُّهم به، ويقول: أين شركائي من الآلهة التي عبدتموها من دوني؛ ليدفعوا عنكم العذاب، وقد كنتم تحاربون الأنبياء والمؤمنين وتعادونهم لأجلهم؟قال العلماء الربانيون: إن الذل في هذا اليوم والعذاب على الكافرين بالله ورسله"},{"id":"1929","jozz":"14","page":"270","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"3","line_end":"5","aya_no":"28","aya_text":"ٱلَّذِينَ تَتَوَفَّىٰهُمُ ٱلۡمَلَٰٓئِكَةُ ظَالِمِيٓ أَنفُسِهِمۡۖ فَأَلۡقَوُاْ ٱلسَّلَمَ مَا كُنَّا نَعۡمَلُ مِن سُوٓءِۭۚ بَلَىٰٓۚ إِنَّ ٱللَّهَ عَلِيمُۢ بِمَا كُنتُمۡ تَعۡمَلُونَ","aya_text_emlaey":"الذين تتوفاهم الملائكة ظالمي أنفسهم فألقوا السلم ما كنا نعمل من سوء بلى إن الله عليم بما كنتم تعملون","aya_tafseer":"[28] الذين تقبض الملائكة أرواحهم في حال ظلمهم لأنفسهم بالكفر، فاستسْلَموا لأمر الله حين رأوا الموت، وأنكروا ما كانوا يعبدون من دون الله، وقالوا: ما كنا نعمل شيئاً من المعاصي، فيقال لهم: كَذَبْتم، قد كنتم تعملونها، إن الله عليم بأعمالكم كلها، وسيجازيكم عليها."},{"id":"1930","jozz":"14","page":"270","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"5","line_end":"6","aya_no":"29","aya_text":"فَٱدۡخُلُوٓاْ أَبۡوَٰبَ جَهَنَّمَ خَٰلِدِينَ فِيهَاۖ فَلَبِئۡسَ مَثۡوَى ٱلۡمُتَكَبِّرِينَ","aya_text_emlaey":"فادخلوا أبواب جهنم خالدين فيها فلبئس مثوى المتكبرين","aya_tafseer":"[29] فادخلوا أبواب جهنم، لا تخرجون منها أبداً، فلبئست مقرّاً للذين تكبَّروا عن الإيمان بالله وعن عبادته وحده وطاعته."},{"id":"1931","jozz":"14","page":"270","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"6","line_end":"8","aya_no":"30","aya_text":"۞ وَقِيلَ لِلَّذِينَ ٱتَّقَوۡاْ مَاذَآ أَنزَلَ رَبُّكُمۡۚ قَالُواْ خَيۡرٗاۗ لِّلَّذِينَ أَحۡسَنُواْ فِي هَٰذِهِ ٱلدُّنۡيَا حَسَنَةٞۚ وَلَدَارُ ٱلۡأٓخِرَةِ خَيۡرٞۚ وَلَنِعۡمَ دَارُ ٱلۡمُتَّقِينَ","aya_text_emlaey":"وقيل للذين اتقوا ماذا أنـزل ربكم قالوا خيرا للذين أحسنوا في هذه الدنيا حسنة ولدار الآخرة خير ولنعم دار المتقين","aya_tafseer":"[30] وإذا قيل للمؤمنين الخائفين من الله: ما الذي أنزل الله على النبي محمد -صلى الله عليه وسلم-؟ قالوا: أنزل الله عليه الخير والهدى. للذين آمنوا بالله ورسوله في هذه الدنيا، ودَعَوْا عِباد الله إلى الإيمان والعمل الصالح، مَكْرُمَة كبيرة من النصر لهم في الدنيا، وسَعَة الرزق، ولَدار الآخرة لهم خير وأعظم مما أُوتوه في الدنيا، ولَنِعْمَ دارُ الذين خافوا الله في الدنيا فاتقَوْا عقابه بأداء فرائضه واجتناب نواهيه دارُ الآخرة."},{"id":"1932","jozz":"14","page":"270","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"9","line_end":"10","aya_no":"31","aya_text":"جَنَّٰتُ عَدۡنٖ يَدۡخُلُونَهَا تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُۖ لَهُمۡ فِيهَا مَا يَشَآءُونَۚ كَذَٰلِكَ يَجۡزِي ٱللَّهُ ٱلۡمُتَّقِينَ","aya_text_emlaey":"جنات عدن يدخلونها تجري من تحتها الأنهار لهم فيها ما يشاءون كذلك يجزي الله المتقين","aya_tafseer":"[31] جنات إقامة لهم، يستقرون فيها، لا يخرجون منها أبداً، تجري من تحت أشجارها وقصورها الأنهار، لهم فيها كل ما تشتهيه أنفسهم، بمثل هذا الجزاء الطيب يجزي الله أهل خشيته وتقواه"},{"id":"1933","jozz":"14","page":"270","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"11","line_end":"12","aya_no":"32","aya_text":"ٱلَّذِينَ تَتَوَفَّىٰهُمُ ٱلۡمَلَٰٓئِكَةُ طَيِّبِينَ يَقُولُونَ سَلَٰمٌ عَلَيۡكُمُ ٱدۡخُلُواْ ٱلۡجَنَّةَ بِمَا كُنتُمۡ تَعۡمَلُونَ","aya_text_emlaey":"الذين تتوفاهم الملائكة طيبين يقولون سلام عليكم ادخلوا الجنة بما كنتم تعملون","aya_tafseer":"[32] الذين تَقْبض الملائكةُ أرواحَهم، وقلوبُهم طاهرة من الكفر، تقول الملائكة لهم: سلام عليكم، تحية خاصة لكم، وسَلِمتم من كل آفة، ادخلوا الجنة بما كنتم تعملون من الإيمان بالله والانقياد لأمره."},{"id":"1934","jozz":"14","page":"270","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"12","line_end":"14","aya_no":"33","aya_text":"هَلۡ يَنظُرُونَ إِلَّآ أَن تَأۡتِيَهُمُ ٱلۡمَلَٰٓئِكَةُ أَوۡ يَأۡتِيَ أَمۡرُ رَبِّكَۚ كَذَٰلِكَ فَعَلَ ٱلَّذِينَ مِن قَبۡلِهِمۡۚ وَمَا ظَلَمَهُمُ ٱللَّهُ وَلَٰكِن كَانُوٓاْ أَنفُسَهُمۡ يَظۡلِمُونَ","aya_text_emlaey":"هل ينظرون إلا أن تأتيهم الملائكة أو يأتي أمر ربك كذلك فعل الذين من قبلهم وما ظلمهم الله ولكن كانوا أنفسهم يظلمون","aya_tafseer":"[33] ما ينتظر المشركون إلا أن تأتيهم الملائكة؛ لتقبض أرواحهم وهم على الكفر، أو يأتي أمر الله بعذاب عاجل يهلكهم، كما كذَّب هؤلاء كذَّب الكفار مِن قبلهم، فأهلكهم الله، وما ظلمهم الله بإهلاكهم، وإنزال العذاب بهم، ولكنهم هم الذين كانوا يظلمون أنفسهم بما جعلهم أهلاً للعذاب."},{"id":"1935","jozz":"14","page":"270","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"15","line_end":"15","aya_no":"34","aya_text":"فَأَصَابَهُمۡ سَيِّـَٔاتُ مَا عَمِلُواْ وَحَاقَ بِهِم مَّا كَانُواْ بِهِۦ يَسۡتَهۡزِءُونَ","aya_text_emlaey":"فأصابهم سيئات ما عملوا وحاق بهم ما كانوا به يستهزئون","aya_tafseer":"[34] فنزلت بهم عقوبة ذنوبهم التي عملوها، وأحاط بهم العذاب الذي كانوا يسخرون منه."},{"id":"1936","jozz":"14","page":"271","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"1","line_end":"3","aya_no":"35","aya_text":"وَقَالَ ٱلَّذِينَ أَشۡرَكُواْ لَوۡ شَآءَ ٱللَّهُ مَا عَبَدۡنَا مِن دُونِهِۦ مِن شَيۡءٖ نَّحۡنُ وَلَآ ءَابَآؤُنَا وَلَا حَرَّمۡنَا مِن دُونِهِۦ مِن شَيۡءٖۚ كَذَٰلِكَ فَعَلَ ٱلَّذِينَ مِن قَبۡلِهِمۡۚ فَهَلۡ عَلَى ٱلرُّسُلِ إِلَّا ٱلۡبَلَٰغُ ٱلۡمُبِينُ","aya_text_emlaey":"وقال الذين أشركوا لو شاء الله ما عبدنا من دونه من شيء نحن ولا آباؤنا ولا حرمنا من دونه من شيء كذلك فعل الذين من قبلهم فهل على الرسل إلا البلاغ المبين","aya_tafseer":"[35] وقال المشركون: لو شاء الله أن نعبده وحده ما عبدنا أحداً غيره، لا نحن ولا آباؤنا مِن قبلنا، ولا حَرَّمْنا شيئاً لم يحرمه، بمثل هذا الاحتجاج الباطل احتج الكفار السابقون، وهم كاذبون؛ فإن الله أمرهم ونهاهم ومكَّنهم من القيام بما كلَّفهم به، وجعل لهم قوة ومشيئة تصدر عنها أفعالهم، فاحتجاجهم بالقضاء والقدر مِن أبطل الباطل مِن بعد إنذار الرسل لهم، فليس على الرسل المنذِرين لهم إلا التبليغ الواضح لما كُلِّفوا به."},{"id":"1937","jozz":"14","page":"271","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"4","line_end":"7","aya_no":"36","aya_text":"وَلَقَدۡ بَعَثۡنَا فِي كُلِّ أُمَّةٖ رَّسُولًا أَنِ ٱعۡبُدُواْ ٱللَّهَ وَٱجۡتَنِبُواْ ٱلطَّٰغُوتَۖ فَمِنۡهُم مَّنۡ هَدَى ٱللَّهُ وَمِنۡهُم مَّنۡ حَقَّتۡ عَلَيۡهِ ٱلضَّلَٰلَةُۚ فَسِيرُواْ فِي ٱلۡأَرۡضِ فَٱنظُرُواْ كَيۡفَ كَانَ عَٰقِبَةُ ٱلۡمُكَذِّبِينَ","aya_text_emlaey":"ولقد بعثنا في كل أمة رسولا أن اعبدوا الله واجتنبوا الطاغوت فمنهم من هدى الله ومنهم من حقت عليه الضلالة فسيروا في الأرض فانظروا كيف كان عاقبة المكذبين","aya_tafseer":"[36] ولقد بعثنا في كل أمة سبقَتْ رسولاً آمراً لهم بعبادة الله وطاعته وحده وتَرْكِ عبادة غيره من الشياطين والأوثان والأموات وغير ذلك مما يتخذ من دون الله وليّاً، فكان منهم مَن هدى الله، فاتبع المرسلين، ومنهم المعاند الذي اتبع سبيل الغيِّ، فوجبت عليه الضلالة، فلم يوفقه الله. فامشوا في الأرض، وأبصروا بأعينكم كيف كان مآل هؤلاء المكذبين، وماذا حلَّ بهم مِن دمار؛ لتعتبروا؟"},{"id":"1938","jozz":"14","page":"271","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"7","line_end":"8","aya_no":"37","aya_text":"إِن تَحۡرِصۡ عَلَىٰ هُدَىٰهُمۡ فَإِنَّ ٱللَّهَ لَا يَهۡدِي مَن يُضِلُّۖ وَمَا لَهُم مِّن نَّٰصِرِينَ","aya_text_emlaey":"إن تحرص على هداهم فإن الله لا يهدي من يضل وما لهم من ناصرين","aya_tafseer":"[37] إن تبذل -أيها الرسول- أقصى جهدك لهداية هؤلاء المشركين فاعلم أن الله لا يهدي مَن يُضِلُّ، وليس لهم من دون الله أحد ينصرهم، ويمنع عنهم عذابه."},{"id":"1939","jozz":"14","page":"271","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"9","line_end":"10","aya_no":"38","aya_text":"وَأَقۡسَمُواْ بِٱللَّهِ جَهۡدَ أَيۡمَٰنِهِمۡ لَا يَبۡعَثُ ٱللَّهُ مَن يَمُوتُۚ بَلَىٰ وَعۡدًا عَلَيۡهِ حَقّٗا وَلَٰكِنَّ أَكۡثَرَ ٱلنَّاسِ لَا يَعۡلَمُونَ","aya_text_emlaey":"وأقسموا بالله جهد أيمانهم لا يبعث الله من يموت بلى وعدا عليه حقا ولكن أكثر الناس لا يعلمون","aya_tafseer":"[38] وحلف هؤلاء المشركون بالله أيماناً مغلَّظة إنَّ الله لا يبعث مَن يموت بعدما بَلِيَ وتفرَّق، بلى سيبعثهم الله حتماً، وعداً عليه حقّاً، ولكن أكثر الناس لا يعلمون قدرة الله على البعث، فينكرونه."},{"id":"1940","jozz":"14","page":"271","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"11","line_end":"12","aya_no":"39","aya_text":"لِيُبَيِّنَ لَهُمُ ٱلَّذِي يَخۡتَلِفُونَ فِيهِ وَلِيَعۡلَمَ ٱلَّذِينَ كَفَرُوٓاْ أَنَّهُمۡ كَانُواْ كَٰذِبِينَ","aya_text_emlaey":"ليبين لهم الذي يختلفون فيه وليعلم الذين كفروا أنهم كانوا كاذبين","aya_tafseer":"[39] يبعث الله جميع العباد؛ ليبين لهم حقيقة البعث الذي اختلفوا فيه، وليعلم الكفار المنكرون له أنهم على باطل، وأنهم كاذبون حين حلفوا أنْ لا بعث."},{"id":"1941","jozz":"14","page":"271","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"12","line_end":"13","aya_no":"40","aya_text":"إِنَّمَا قَوۡلُنَا لِشَيۡءٍ إِذَآ أَرَدۡنَٰهُ أَن نَّقُولَ لَهُۥ كُن فَيَكُونُ","aya_text_emlaey":"إنما قولنا لشيء إذا أردناه أن نقول له كن فيكون","aya_tafseer":"[40] إنَّ أمر البعث يسير علينا، فإنَّا إذا أردنا شيئاً فإنما نقول له: «كن»، فإذا هو كائن موجود."},{"id":"1942","jozz":"14","page":"271","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"13","line_end":"15","aya_no":"41","aya_text":"وَٱلَّذِينَ هَاجَرُواْ فِي ٱللَّهِ مِنۢ بَعۡدِ مَا ظُلِمُواْ لَنُبَوِّئَنَّهُمۡ فِي ٱلدُّنۡيَا حَسَنَةٗۖ وَلَأَجۡرُ ٱلۡأٓخِرَةِ أَكۡبَرُۚ لَوۡ كَانُواْ يَعۡلَمُونَ","aya_text_emlaey":"والذين هاجروا في الله من بعد ما ظلموا لنبوئنهم في الدنيا حسنة ولأجر الآخرة أكبر لو كانوا يعلمون","aya_tafseer":"[41] والذين تركوا ديارهم مِن أجل الله، فهاجروا بعدما وقع عليهم الظلم، لنسكننهم في الدنيا داراً حسنة، ولأَجر الآخرة أكبر؛ لأن ثوابهم فيها الجنة. لو كان المتخلفون عن الهجرة يعلمون علم يقين ما عند الله من الأجر والثواب للمهاجرين في سبيله، ما تخلَّف منهم أحد عن ذلك."},{"id":"1943","jozz":"14","page":"271","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"15","line_end":"15","aya_no":"42","aya_text":"ٱلَّذِينَ صَبَرُواْ وَعَلَىٰ رَبِّهِمۡ يَتَوَكَّلُونَ","aya_text_emlaey":"الذين صبروا وعلى ربهم يتوكلون","aya_tafseer":"[42] هؤلاء المهاجرون في سبيل الله هم الذين صبروا على أوامر الله وعن نواهيه وعلى أقداره المؤلمة، وعلى ربهم وحده يعتمدون، فاستحقوا هذه المنزلة العظيمة."},{"id":"1944","jozz":"14","page":"272","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"1","line_end":"2","aya_no":"43","aya_text":"وَمَآ أَرۡسَلۡنَا مِن قَبۡلِكَ إِلَّا رِجَالٗا نُّوحِيٓ إِلَيۡهِمۡۖ فَسۡـَٔلُوٓاْ أَهۡلَ ٱلذِّكۡرِ إِن كُنتُمۡ لَا تَعۡلَمُونَ","aya_text_emlaey":"وما أرسلنا من قبلك إلا رجالا نوحي إليهم فاسألوا أهل الذكر إن كنتم لا تعلمون","aya_tafseer":"[43] وما أرسلنا في السابقين قبلك -أيها الرسول- إلا رسلاً من الرجال لا من الملائكة، نوحي إليهم، وإن كنتم -يا مشركي قريش- لا تصدقون بذلك فاسألوا علماءَ أهل الكتب السابقة، يخبروكم أن الأنبياء كانوا بشراً، إن كنتم لا تعلمون أنهم بشر. والآية عامة في كل مسألة من مسائل الدين، إذا لم يكن عند الإنسان علم منها أن يسأل من يعلمها من العلماء الراسخين في العلم."},{"id":"1945","jozz":"14","page":"272","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"2","line_end":"3","aya_no":"44","aya_text":"بِٱلۡبَيِّنَٰتِ وَٱلزُّبُرِۗ وَأَنزَلۡنَآ إِلَيۡكَ ٱلذِّكۡرَ لِتُبَيِّنَ لِلنَّاسِ مَا نُزِّلَ إِلَيۡهِمۡ وَلَعَلَّهُمۡ يَتَفَكَّرُونَ","aya_text_emlaey":"بالبينات والزبر وأنـزلنا إليك الذكر لتبين للناس ما نـزل إليهم ولعلهم يتفكرون","aya_tafseer":"[44] وأَرْسَلْنا الرسل السابقين بالدلائل الواضحة وبالكتب السماوية، وأنزلنا إليك -أيها الرسول- القرآن؛ لتوضح للناس ما خفي مِن معانيه وأحكامه، ولكي يتدبروه ويهتدوا به."},{"id":"1946","jozz":"14","page":"272","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"4","line_end":"5","aya_no":"45","aya_text":"أَفَأَمِنَ ٱلَّذِينَ مَكَرُواْ ٱلسَّيِّـَٔاتِ أَن يَخۡسِفَ ٱللَّهُ بِهِمُ ٱلۡأَرۡضَ أَوۡ يَأۡتِيَهُمُ ٱلۡعَذَابُ مِنۡ حَيۡثُ لَا يَشۡعُرُونَ","aya_text_emlaey":"أفأمن الذين مكروا السيئات أن يخسف الله بهم الأرض أو يأتيهم العذاب من حيث لا يشعرون","aya_tafseer":"[45] أفأمن الكفار المدبِّرون للمكايد أن يخسف الله بهم الأرض كما فَعَل بقارون، أو يأتيهم العذاب من مكان لا يُحِسُّونه ولا يتوقعونه."},{"id":"1947","jozz":"14","page":"272","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"5","line_end":"6","aya_no":"46","aya_text":"أَوۡ يَأۡخُذَهُمۡ فِي تَقَلُّبِهِمۡ فَمَا هُم بِمُعۡجِزِينَ","aya_text_emlaey":"أو يأخذهم في تقلبهم فما هم بمعجزين","aya_tafseer":"[46] أو يأخذهم العذاب، وهم يتقلبون في أسفارهم وتصرفهم؟ فما هم بسابقين الله ولا فائتيه ولا ناجين من عذابه؛ لأنه القوي الذي لا يعجزه شيء."},{"id":"1948","jozz":"14","page":"272","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"6","line_end":"7","aya_no":"47","aya_text":"أَوۡ يَأۡخُذَهُمۡ عَلَىٰ تَخَوُّفٖ فَإِنَّ رَبَّكُمۡ لَرَءُوفٞ رَّحِيمٌ","aya_text_emlaey":"أو يأخذهم على تخوف فإن ربكم لرءوف رحيم","aya_tafseer":"[47] أو يأخذهم الله بنقص من الأموال والأنفس والثمرات، أو في حال خوفهم مِن أخْذه لهم، فإن ربكم ليرحم خلقه رحمة واسعة في عاجلهم وآجلهم."},{"id":"1949","jozz":"14","page":"272","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"7","line_end":"8","aya_no":"48","aya_text":"أَوَلَمۡ يَرَوۡاْ إِلَىٰ مَا خَلَقَ ٱللَّهُ مِن شَيۡءٖ يَتَفَيَّؤُاْ ظِلَٰلُهُۥ عَنِ ٱلۡيَمِينِ وَٱلشَّمَآئِلِ سُجَّدٗا لِّلَّهِ وَهُمۡ دَٰخِرُونَ","aya_text_emlaey":"أو لم يروا إلى ما خلق الله من شيء يتفيأ ظلاله عن اليمين والشمائل سجدا لله وهم داخرون","aya_tafseer":"[48] أَعَمِيَ هؤلاء الكفار، فلم ينظروا إلى ما خلق الله من شيء له ظل، كالجبال والأشجار، تميل ظلالها تارة يميناً وتارة شمالاً؛ تبعاً لحركة الشمس نهاراً والقمرِ ليلاً، كلها خاضعة لعظمة ربها وجلاله، وهي تحت تسخيره وتدبيره وقهره؟"},{"id":"1950","jozz":"14","page":"272","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"9","line_end":"10","aya_no":"49","aya_text":"وَلِلَّهِۤ يَسۡجُدُۤ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِ مِن دَآبَّةٖ وَٱلۡمَلَٰٓئِكَةُ وَهُمۡ لَا يَسۡتَكۡبِرُونَ","aya_text_emlaey":"ولله يسجد ما في السموات وما في الأرض من دابة والملائكة وهم لا يستكبرون","aya_tafseer":"[49] ولله وحده يسجد كل ما في السموات وما في الأرض مِن دابة، والملائكة يسجدون لله، وهم لا يستكبرون عن عبادته. وخصَّهم بالذكر بعد العموم لفَضْلهم وشرفهم وكثرة عبادتهم."},{"id":"1951","jozz":"14","page":"272","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"10","line_end":"11","aya_no":"50","aya_text":"يَخَافُونَ رَبَّهُم مِّن فَوۡقِهِمۡ وَيَفۡعَلُونَ مَا يُؤۡمَرُونَ۩","aya_text_emlaey":"يخافون ربهم من فوقهم ويفعلون ما يؤمرون","aya_tafseer":"[50] يخاف الملائكة ربهم الذي هو فوقهم بالذات والقهر وكمال الصفات، ويفعلون ما يُؤْمرون به من طاعة الله. وفي الآية إثبات صفة العلو والفوقية لله على جميع خلقه، كما يليق بجلاله وكماله."},{"id":"1952","jozz":"14","page":"272","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"11","line_end":"12","aya_no":"51","aya_text":"۞ وَقَالَ ٱللَّهُ لَا تَتَّخِذُوٓاْ إِلَٰهَيۡنِ ٱثۡنَيۡنِۖ إِنَّمَا هُوَ إِلَٰهٞ وَٰحِدٞ فَإِيَّٰيَ فَٱرۡهَبُونِ","aya_text_emlaey":"وقال الله لا تتخذوا إلهين اثنين إنما هو إله واحد فإياي فارهبون","aya_tafseer":"[51] وقال الله لعباده: لا تعبدوا إلهين اثنين، إنما معبودكم إله واحد، فخافوني دون سواي."},{"id":"1953","jozz":"14","page":"272","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"12","line_end":"13","aya_no":"52","aya_text":"وَلَهُۥ مَا فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ وَلَهُ ٱلدِّينُ وَاصِبًاۚ أَفَغَيۡرَ ٱللَّهِ تَتَّقُونَ","aya_text_emlaey":"وله ما في السموات والأرض وله الدين واصبا أفغير الله تتقون","aya_tafseer":"[52] ولله كل ما في السموات والأرض خلقاً وملكاً وعبيداً، وله وحده العبادة والطاعة والإخلاص دائماً، أيليق بكم أن تخافوا غير الله وتعبدوه؟"},{"id":"1954","jozz":"14","page":"272","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"13","line_end":"14","aya_no":"53","aya_text":"وَمَا بِكُم مِّن نِّعۡمَةٖ فَمِنَ ٱللَّهِۖ ثُمَّ إِذَا مَسَّكُمُ ٱلضُّرُّ فَإِلَيۡهِ تَجۡـَٔرُونَ","aya_text_emlaey":"وما بكم من نعمة فمن الله ثم إذا مسكم الضر فإليه تجأرون","aya_tafseer":"[53] وما بكم مِن نعمةِ هدايةٍ، أو صحةِ جسم، وسَعَة رزقٍ، وولدٍ، وغير ذلك، فمِنَ الله وحده، فهو المُنْعِم بها عليكم، ثم إذا نزل بكم السَّقَم والبلاء والقحط فإلى الله وحده تَضِجُّون بالدعاء."},{"id":"1955","jozz":"14","page":"272","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"14","line_end":"15","aya_no":"54","aya_text":"ثُمَّ إِذَا كَشَفَ ٱلضُّرَّ عَنكُمۡ إِذَا فَرِيقٞ مِّنكُم بِرَبِّهِمۡ يُشۡرِكُونَ","aya_text_emlaey":"ثم إذا كشف الضر عنكم إذا فريق منكم بربهم يشركون","aya_tafseer":"[54] ثم إذا كشف عنكم البلاء والسَّقَم، إذا جماعة منكم بربهم الـمُنْعِم عليهم بالنجاة يتخذون معه الشركاء والأولياء."},{"id":"1956","jozz":"14","page":"273","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"1","line_end":"1","aya_no":"55","aya_text":"لِيَكۡفُرُواْ بِمَآ ءَاتَيۡنَٰهُمۡۚ فَتَمَتَّعُواْ فَسَوۡفَ تَعۡلَمُونَ","aya_text_emlaey":"ليكفروا بما آتيناهم فتمتعوا فسوف تعلمون","aya_tafseer":"[55] ليجحدوا نعمنا عليهم، ومنها كَشْفُ البلاء عنهم، فاستمتعوا بدنياكم، ومصيرُها إلى الزوال، فسوف تعلمون عاقبة كفركم وعصيانكم."},{"id":"1957","jozz":"14","page":"273","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"1","line_end":"3","aya_no":"56","aya_text":"وَيَجۡعَلُونَ لِمَا لَا يَعۡلَمُونَ نَصِيبٗا مِّمَّا رَزَقۡنَٰهُمۡۗ تَٱللَّهِ لَتُسۡـَٔلُنَّ عَمَّا كُنتُمۡ تَفۡتَرُونَ","aya_text_emlaey":"ويجعلون لما لا يعلمون نصيبا مما رزقناهم تالله لتسألن عما كنتم تفترون","aya_tafseer":"[56] ومِن قبيح أعمال المشركين أنهم يجعلون للأصنام التي اتخذوها آلهة -وهي لا تعلم شيئاً ولا تنفع ولا تضر- جزءاً من أموالهم التي رزقهم الله بها تقرباً إليها. تالله لتسألُنَّ يوم القيامة عما كنتم تختلقونه من الكذب على الله."},{"id":"1958","jozz":"14","page":"273","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"3","line_end":"3","aya_no":"57","aya_text":"وَيَجۡعَلُونَ لِلَّهِ ٱلۡبَنَٰتِ سُبۡحَٰنَهُۥ وَلَهُم مَّا يَشۡتَهُونَ","aya_text_emlaey":"ويجعلون لله البنات سبحانه ولهم ما يشتهون","aya_tafseer":"[57] ويجعل الكفار لله البناتِ، فيقولون: الملائكة بنات الله، تنزَّه الله عن قولهم، ويجعلون لأنفسهم ما يحبون من البنين."},{"id":"1959","jozz":"14","page":"273","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"4","line_end":"4","aya_no":"58","aya_text":"وَإِذَا بُشِّرَ أَحَدُهُم بِٱلۡأُنثَىٰ ظَلَّ وَجۡهُهُۥ مُسۡوَدّٗا وَهُوَ كَظِيمٞ","aya_text_emlaey":"وإذا بشر أحدهم بالأنثى ظل وجهه مسودا وهو كظيم","aya_tafseer":"[58] وإذا جاء مَن يخبر أحدَهم بولادة أنثى اسودَّ وجهه؛ كراهية لما سمع، وامتلأ غمّاً وحزناً."},{"id":"1960","jozz":"14","page":"273","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"5","line_end":"6","aya_no":"59","aya_text":"يَتَوَٰرَىٰ مِنَ ٱلۡقَوۡمِ مِن سُوٓءِ مَا بُشِّرَ بِهِۦٓۚ أَيُمۡسِكُهُۥ عَلَىٰ هُونٍ أَمۡ يَدُسُّهُۥ فِي ٱلتُّرَابِۗ أَلَا سَآءَ مَا يَحۡكُمُونَ","aya_text_emlaey":"يتوارى من القوم من سوء ما بشر به أيمسكه على هون أم يدسه في التراب ألا ساء ما يحكمون","aya_tafseer":"[59] يستخفي مِن قومه كراهة أن يلقاهم متلبساً بما ساءه من الحزن والعار؛ بسبب البنت التي وُلِدت له، ومتحيراً في أمر هذه المولودة: أيبقيها حية على ذُلٍّ وهَوان، أم يدفنها حية في التراب؟ ألا بئس الحكم الذي حكموه مِن جَعْل البنات لله والذكور لهم."},{"id":"1961","jozz":"14","page":"273","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"6","line_end":"7","aya_no":"60","aya_text":"لِلَّذِينَ لَا يُؤۡمِنُونَ بِٱلۡأٓخِرَةِ مَثَلُ ٱلسَّوۡءِۖ وَلِلَّهِ ٱلۡمَثَلُ ٱلۡأَعۡلَىٰۚ وَهُوَ ٱلۡعَزِيزُ ٱلۡحَكِيمُ","aya_text_emlaey":"للذين لا يؤمنون بالآخرة مثل السوء ولله المثل الأعلى وهو العزيز الحكيم","aya_tafseer":"[60] للذين لا يؤمنون بالآخرة ولا يعملون لها، الصفة القبيحة من العجز والحاجة والجهل والكفر، ولله الصفات العليا من الكمال والاستغناء عن خلقه، وهو العزيز في ملكه، الحكيم في تدبيره."},{"id":"1962","jozz":"14","page":"273","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"8","line_end":"10","aya_no":"61","aya_text":"وَلَوۡ يُؤَاخِذُ ٱللَّهُ ٱلنَّاسَ بِظُلۡمِهِم مَّا تَرَكَ عَلَيۡهَا مِن دَآبَّةٖ وَلَٰكِن يُؤَخِّرُهُمۡ إِلَىٰٓ أَجَلٖ مُّسَمّٗىۖ فَإِذَا جَآءَ أَجَلُهُمۡ لَا يَسۡتَـٔۡخِرُونَ سَاعَةٗ وَلَا يَسۡتَقۡدِمُونَ","aya_text_emlaey":"ولو يؤاخذ الله الناس بظلمهم ما ترك عليها من دابة ولكن يؤخرهم إلى أجل مسمى فإذا جاء أجلهم لا يستأخرون ساعة ولا يستقدمون","aya_tafseer":"[61] ولو يؤاخذ الله الناس بكفرهم وافترائهم ما ترك على الأرض مَن يتحرَّكُ، ولكن يبقيهم إلى وقت محدد هو نهاية آجالهم، فإذا جاء أجلهم لا يتأخرون عنه وقتاً يسيراً، ولا يتقدمون."},{"id":"1963","jozz":"14","page":"273","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"10","line_end":"12","aya_no":"62","aya_text":"وَيَجۡعَلُونَ لِلَّهِ مَا يَكۡرَهُونَۚ وَتَصِفُ أَلۡسِنَتُهُمُ ٱلۡكَذِبَ أَنَّ لَهُمُ ٱلۡحُسۡنَىٰۚ لَا جَرَمَ أَنَّ لَهُمُ ٱلنَّارَ وَأَنَّهُم مُّفۡرَطُونَ","aya_text_emlaey":"ويجعلون لله ما يكرهون وتصف ألسنتهم الكذب أن لهم الحسنى لا جرم أن لهم النار وأنهم مفرطون","aya_tafseer":"[62] ومن قبائحهم: أنهم يجعلون لله ما يكرهونه لأنفسهم من البنات، وتقول ألسنتهم كذباً: إن لهم حسن العاقبة، حقّاً أن لهم النار، وأنهم فيها مَتْروكون مَنْسيُّون."},{"id":"1964","jozz":"14","page":"273","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"12","line_end":"14","aya_no":"63","aya_text":"تَٱللَّهِ لَقَدۡ أَرۡسَلۡنَآ إِلَىٰٓ أُمَمٖ مِّن قَبۡلِكَ فَزَيَّنَ لَهُمُ ٱلشَّيۡطَٰنُ أَعۡمَٰلَهُمۡ فَهُوَ وَلِيُّهُمُ ٱلۡيَوۡمَ وَلَهُمۡ عَذَابٌ أَلِيمٞ","aya_text_emlaey":"تالله لقد أرسلنا إلى أمم من قبلك فزين لهم الشيطان أعمالهم فهو وليهم اليوم ولهم عذاب أليم","aya_tafseer":"[63] تالله لقد أرسلنا رسلاً إلى أمم مِن قبلك -أيها الرسول- فحسَّن لهم الشيطان ما عملوه من الكفر والتكذيب وعبادة غير الله، فهو متولٍّ إغواءهم في الدنيا، ولهم في الآخرة عذاب أليم موجع."},{"id":"1965","jozz":"14","page":"273","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"14","line_end":"15","aya_no":"64","aya_text":"وَمَآ أَنزَلۡنَا عَلَيۡكَ ٱلۡكِتَٰبَ إِلَّا لِتُبَيِّنَ لَهُمُ ٱلَّذِي ٱخۡتَلَفُواْ فِيهِ وَهُدٗى وَرَحۡمَةٗ لِّقَوۡمٖ يُؤۡمِنُونَ","aya_text_emlaey":"وما أنـزلنا عليك الكتاب إلا لتبين لهم الذي اختلفوا فيه وهدى ورحمة لقوم يؤمنون","aya_tafseer":"[64] وما أنزلنا عليك القرآن -أيها الرسول- إلا لتوضح للناس ما اختلفوا فيه من الدين والأحكام؛ لتقوم الحجة عليهم ببيانك الذي لا يترك للباطل مسلكاً إلى النفوس، ولكون القرآن هدىً لا يترك مجالاً للحَيْرة، ورحمة للمؤمنين في اتباعهم الهدى ومجانبتهم الضلال."},{"id":"1966","jozz":"14","page":"274","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"1","line_end":"2","aya_no":"65","aya_text":"وَٱللَّهُ أَنزَلَ مِنَ ٱلسَّمَآءِ مَآءٗ فَأَحۡيَا بِهِ ٱلۡأَرۡضَ بَعۡدَ مَوۡتِهَآۚ إِنَّ فِي ذَٰلِكَ لَأٓيَةٗ لِّقَوۡمٖ يَسۡمَعُونَ","aya_text_emlaey":"والله أنـزل من السماء ماء فأحيا به الأرض بعد موتها إن في ذلك لآية لقوم يسمعون","aya_tafseer":"[65] والله أنزل من السحاب مطراً، فأخرج به النبات من الأرض بعد أن كانت قاحلة يابسة، إن في إنزال المطر وإنبات النبات لَدليلاً على قدرة الله على البعث وعلى الوحدانية، لقوم يسمعون، ويتدبرون، ويطيعون الله، ويتقونه."},{"id":"1967","jozz":"14","page":"274","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"2","line_end":"3","aya_no":"66","aya_text":"وَإِنَّ لَكُمۡ فِي ٱلۡأَنۡعَٰمِ لَعِبۡرَةٗۖ نُّسۡقِيكُم مِّمَّا فِي بُطُونِهِۦ مِنۢ بَيۡنِ فَرۡثٖ وَدَمٖ لَّبَنًا خَالِصٗا سَآئِغٗا لِّلشَّٰرِبِينَ","aya_text_emlaey":"وإن لكم في الأنعام لعبرة نسقيكم مما في بطونه من بين فرث ودم لبنا خالصا سائغا للشاربين","aya_tafseer":"[66] وإن لكم -أيها الناس- في الأنعام -وهي الإبل والبقر والغنم- لَعظة، فقد شاهدتم أننا نسقيكم من ضروعها لبناً خارجاً مِن بين فَرْث -وهو ما في الكَرِش- وبين دم خالصاً من كل الشوائب، لذيذاً لا يَغَصُّ به مَن شَرِبَه."},{"id":"1968","jozz":"14","page":"274","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"4","line_end":"5","aya_no":"67","aya_text":"وَمِن ثَمَرَٰتِ ٱلنَّخِيلِ وَٱلۡأَعۡنَٰبِ تَتَّخِذُونَ مِنۡهُ سَكَرٗا وَرِزۡقًا حَسَنًاۚ إِنَّ فِي ذَٰلِكَ لَأٓيَةٗ لِّقَوۡمٖ يَعۡقِلُونَ","aya_text_emlaey":"ومن ثمرات النخيل والأعناب تتخذون منه سكرا ورزقا حسنا إن في ذلك لآية لقوم يعقلون","aya_tafseer":"[67] ومِن نِعَمنا عَليكم ما تأخذونه من ثمرات النخيل والأعناب، فتجعلونه خمراً مُسْكراً -وهذا قبل تحريمها- وطعاماً طيباً . إن فيما ذكر لَدليلاً على قدرة الله لِقومٍ يعقلون البراهين فيعتبرون بها."},{"id":"1969","jozz":"14","page":"274","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"5","line_end":"6","aya_no":"68","aya_text":"وَأَوۡحَىٰ رَبُّكَ إِلَى ٱلنَّحۡلِ أَنِ ٱتَّخِذِي مِنَ ٱلۡجِبَالِ بُيُوتٗا وَمِنَ ٱلشَّجَرِ وَمِمَّا يَعۡرِشُونَ","aya_text_emlaey":"وأوحى ربك إلى النحل أن اتخذي من الجبال بيوتا ومن الشجر ومما يعرشون","aya_tafseer":"[68] وألْهَمَ ربك -أيها الرسول- النحل بأن اجعلي لك بيوتاً في الجبال، وفي الشجر، وفيما يبني الناس من البيوت والسُّقُف."},{"id":"1970","jozz":"14","page":"274","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"6","line_end":"9","aya_no":"69","aya_text":"ثُمَّ كُلِي مِن كُلِّ ٱلثَّمَرَٰتِ فَٱسۡلُكِي سُبُلَ رَبِّكِ ذُلُلٗاۚ يَخۡرُجُ مِنۢ بُطُونِهَا شَرَابٞ مُّخۡتَلِفٌ أَلۡوَٰنُهُۥ فِيهِ شِفَآءٞ لِّلنَّاسِۚ إِنَّ فِي ذَٰلِكَ لَأٓيَةٗ لِّقَوۡمٖ يَتَفَكَّرُونَ","aya_text_emlaey":"ثم كلي من كل الثمرات فاسلكي سبل ربك ذللا يخرج من بطونها شراب مختلف ألوانه فيه شفاء للناس إن في ذلك لآية لقوم يتفكرون","aya_tafseer":"[69] ثم كُلي مِن كل ثمرة تشتهينها، فاسلكي طرق ربك مذللة لك؛ لطلب الرزق في الجبال وخلال الشجر، وقد جعلها سهلة عليكِ، لا تضلي في العَوْد إليها وإن بَعُدَتْ. يخرج من بطون النحل عسل مختلف الألوان مِن بياض وصفرة وحمرة وغير ذلك، فيه شفاء للناس من الأمراض. إن فيما يصنعه النحل لَدلالة قوية على قدرة خالقها لقوم يتفكرون، فيعتبرون."},{"id":"1971","jozz":"14","page":"274","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"9","line_end":"10","aya_no":"70","aya_text":"وَٱللَّهُ خَلَقَكُمۡ ثُمَّ يَتَوَفَّىٰكُمۡۚ وَمِنكُم مَّن يُرَدُّ إِلَىٰٓ أَرۡذَلِ ٱلۡعُمُرِ لِكَيۡ لَا يَعۡلَمَ بَعۡدَ عِلۡمٖ شَيۡـًٔاۚ إِنَّ ٱللَّهَ عَلِيمٞ قَدِيرٞ","aya_text_emlaey":"والله خلقكم ثم يتوفاكم ومنكم من يرد إلى أرذل العمر لكي لا يعلم بعد علم شيئا إن الله عليم قدير","aya_tafseer":"[70] والله سبحانه وتعالى خلقكم ثم يميتكم في نهاية أعماركم، ومنكم مَن يصير إلى أردأ العمر وهو الهرم، كما كان في طفولته لا يعلم شيئاً مما كان يعلمه، إن الله عليم قدير، أحاط علمه وقدرته بكل شيء، فالله الذي ردَّ الإنسان إلى هذه الحالة قادر على أن يميته، ثم يبعثه."},{"id":"1972","jozz":"14","page":"274","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"11","line_end":"13","aya_no":"71","aya_text":"وَٱللَّهُ فَضَّلَ بَعۡضَكُمۡ عَلَىٰ بَعۡضٖ فِي ٱلرِّزۡقِۚ فَمَا ٱلَّذِينَ فُضِّلُواْ بِرَآدِّي رِزۡقِهِمۡ عَلَىٰ مَا مَلَكَتۡ أَيۡمَٰنُهُمۡ فَهُمۡ فِيهِ سَوَآءٌۚ أَفَبِنِعۡمَةِ ٱللَّهِ يَجۡحَدُونَ","aya_text_emlaey":"والله فضل بعضكم على بعض في الرزق فما الذين فضلوا برادي رزقهم على ما ملكت أيمانهم فهم فيه سواء أفبنعمة الله يجحدون","aya_tafseer":"[71] والله فَضَّل بعضكم على بعض فيما أعطاكم في الدنيا من الرزق، فمنكم غني ومنكم فقير، ومنكم مالك ومنكم مملوك، فلا يعطي المالكون مملوكيهم مما أعطاهم الله ما يصيرون به شركاء لهم متساوين معهم في المال، فإذا لم يرضوا بذلك لأنفسهم، فلماذا رضوا أن يجعلوا لله شركاء مِن عبيده؟ إن هذا لَمن أعظم الظلم والجحود لِنعم الله عز وجل."},{"id":"1973","jozz":"14","page":"274","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"13","line_end":"15","aya_no":"72","aya_text":"وَٱللَّهُ جَعَلَ لَكُم مِّنۡ أَنفُسِكُمۡ أَزۡوَٰجٗا وَجَعَلَ لَكُم مِّنۡ أَزۡوَٰجِكُم بَنِينَ وَحَفَدَةٗ وَرَزَقَكُم مِّنَ ٱلطَّيِّبَٰتِۚ أَفَبِٱلۡبَٰطِلِ يُؤۡمِنُونَ وَبِنِعۡمَتِ ٱللَّهِ هُمۡ يَكۡفُرُونَ","aya_text_emlaey":"والله جعل لكم من أنفسكم أزواجا وجعل لكم من أزواجكم بنين وحفدة ورزقكم من الطيبات أفبالباطل يؤمنون وبنعمة الله هم يكفرون","aya_tafseer":"[72] والله سبحانه جعل مِن جنسكم أزواجاً؛ لتستريح نفوسكم معهن، وجعل لكم منهن الأبناء ومِن نسلهنَّ الأحفاد، ورزقكم من الأطعمة الطيبة من الثمار والحبوب واللحوم وغير ذلك. أفبالباطل من ألوهية شركائهم يؤمنون، وبنعم الله التي لا تحصى يجحدون، ولا يشكرون له بإفراده جل وعلا بالعبادة؟"},{"id":"1974","jozz":"14","page":"275","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"1","line_end":"2","aya_no":"73","aya_text":"وَيَعۡبُدُونَ مِن دُونِ ٱللَّهِ مَا لَا يَمۡلِكُ لَهُمۡ رِزۡقٗا مِّنَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِ شَيۡـٔٗا وَلَا يَسۡتَطِيعُونَ","aya_text_emlaey":"ويعبدون من دون الله ما لا يملك لهم رزقا من السموات والأرض شيئا ولا يستطيعون","aya_tafseer":"[73] ويعبد المشركون أصناماً لا تملك أن تعطيهم شيئاً من الرزق من السماء كالمطر، ولا من الأرض كالزرع، فهم لا يملكون شيئاً، ولا يتأتى منهم أن يملكوه؛ لأنهم لا يقدرون."},{"id":"1975","jozz":"14","page":"275","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"2","line_end":"3","aya_no":"74","aya_text":"فَلَا تَضۡرِبُواْ لِلَّهِ ٱلۡأَمۡثَالَۚ إِنَّ ٱللَّهَ يَعۡلَمُ وَأَنتُمۡ لَا تَعۡلَمُونَ","aya_text_emlaey":"فلا تضربوا لله الأمثال إن الله يعلم وأنتم لا تعلمون","aya_tafseer":"[74] وإذا عَلِمتم أن الأصنام والأوثان لا تنفع، فلا تجعلوا -أيها الناس- لله أشباهاً مماثلين له مِن خَلْقه تشركونهم معه في العبادة. إن الله يعلم ما تفعلون، وأنتم غافلون لا تعلمون خطأكم وسوء عاقبتكم."},{"id":"1976","jozz":"14","page":"275","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"3","line_end":"6","aya_no":"75","aya_text":"۞ ضَرَبَ ٱللَّهُ مَثَلًا عَبۡدٗا مَّمۡلُوكٗا لَّا يَقۡدِرُ عَلَىٰ شَيۡءٖ وَمَن رَّزَقۡنَٰهُ مِنَّا رِزۡقًا حَسَنٗا فَهُوَ يُنفِقُ مِنۡهُ سِرّٗا وَجَهۡرًاۖ هَلۡ يَسۡتَوُۥنَۚ ٱلۡحَمۡدُ لِلَّهِۚ بَلۡ أَكۡثَرُهُمۡ لَا يَعۡلَمُونَ","aya_text_emlaey":"ضرب الله مثلا عبدا مملوكا لا يقدر على شيء ومن رزقناه منا رزقا حسنا فهو ينفق منه سرا وجهرا هل يستوون الحمد لله بل أكثرهم لا يعلمون","aya_tafseer":"[75] ضرب الله مثلاً بيَّن فيه فساد عقيدة أهل الشرك: رجلاً مملوكاً عاجزاً عن التصرف لا يملك شيئاً، ورجلاً آخر حرّاً، له مال حلال رزَقَه الله به، يملك التصرف فيه، ويعطي منه في الخفاء والعلن، فهل يقول عاقل بالتساوي بين الرجلين؟ فكذلك الله الخالق المالك المتصرف لا يستوي مع خلقه وعبيده، فكيف تُسَوُّون بينهما؟ الحمد لله وحده، فهو المستحق للحمد والثناء، بل أكثر المشركين لا يعلمون أن الحمد والنعمة لله، وأنه وحده المستحق للعبادة."},{"id":"1977","jozz":"14","page":"275","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"6","line_end":"9","aya_no":"76","aya_text":"وَضَرَبَ ٱللَّهُ مَثَلٗا رَّجُلَيۡنِ أَحَدُهُمَآ أَبۡكَمُ لَا يَقۡدِرُ عَلَىٰ شَيۡءٖ وَهُوَ كَلٌّ عَلَىٰ مَوۡلَىٰهُ أَيۡنَمَا يُوَجِّههُّ لَا يَأۡتِ بِخَيۡرٍ هَلۡ يَسۡتَوِي هُوَ وَمَن يَأۡمُرُ بِٱلۡعَدۡلِ وَهُوَ عَلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ","aya_text_emlaey":"وضرب الله مثلا رجلين أحدهما أبكم لا يقدر على شيء وهو كل على مولاه أينما يوجهه لا يأت بخير هل يستوي هو ومن يأمر بالعدل وهو على صراط مستقيم","aya_tafseer":"[76] وضرب الله مثلاً آخر لبطلان الشرك رجلين: أحدهما أخرس أصم لا يَفْهَم ولا يُفْهِم، لا يقدر على منفعة نفسه أو غيره، وهو عبء ثقيل على مَن يَلي أمره ويعوله، إذا أرسله لأمر يقضيه لا ينجح، ولا يعود عليه بخير، ورجل آخر سليم الحواس، ينفع نفسه وغيره، يأمر بالإنصاف، وهو على طريق واضح لا عوج فيه، فهل يستوي الرجلان في نظر العقلاء؟ فكيف تُسَوُّون بين الصنم الأبكم الأصمِّ وبين الله القادر المنعم بكل خير؟"},{"id":"1978","jozz":"14","page":"275","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"9","line_end":"11","aya_no":"77","aya_text":"وَلِلَّهِ غَيۡبُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ وَمَآ أَمۡرُ ٱلسَّاعَةِ إِلَّا كَلَمۡحِ ٱلۡبَصَرِ أَوۡ هُوَ أَقۡرَبُۚ إِنَّ ٱللَّهَ عَلَىٰ كُلِّ شَيۡءٖ قَدِيرٞ","aya_text_emlaey":"ولله غيب السموات والأرض وما أمر الساعة إلا كلمح البصر أو هو أقرب إن الله على كل شيء قدير","aya_tafseer":"[77] ولله سبحانه وتعالى عِلْمُ ما غاب في السموات والأرض، وما شأن القيامة في سرعة مجيئها إلا كنظرة سريعة بالبصر، بل هو أسرع من ذلك. إن الله على كل شيء قدير."},{"id":"1979","jozz":"14","page":"275","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"12","line_end":"14","aya_no":"78","aya_text":"وَٱللَّهُ أَخۡرَجَكُم مِّنۢ بُطُونِ أُمَّهَٰتِكُمۡ لَا تَعۡلَمُونَ شَيۡـٔٗا وَجَعَلَ لَكُمُ ٱلسَّمۡعَ وَٱلۡأَبۡصَٰرَ وَٱلۡأَفۡـِٔدَةَ لَعَلَّكُمۡ تَشۡكُرُونَ","aya_text_emlaey":"والله أخرجكم من بطون أمهاتكم لا تعلمون شيئا وجعل لكم السمع والأبصار والأفئدة لعلكم تشكرون","aya_tafseer":"[78] والله سبحانه وتعالى أخرجكم مِن بطون أمهاتكم بعد مدة الحمل، لا تدركون شيئاً مما حولكم، وجعل لكم وسائل الإدراك من السمع والبصر والقلوب؛ لعلكم تشكرون لله تعالى على تلك النعم، وتفردونه عز وجل بالعبادة."},{"id":"1980","jozz":"14","page":"275","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"14","line_end":"15","aya_no":"79","aya_text":"أَلَمۡ يَرَوۡاْ إِلَى ٱلطَّيۡرِ مُسَخَّرَٰتٖ فِي جَوِّ ٱلسَّمَآءِ مَا يُمۡسِكُهُنَّ إِلَّا ٱللَّهُۚ إِنَّ فِي ذَٰلِكَ لَأٓيَٰتٖ لِّقَوۡمٖ يُؤۡمِنُونَ","aya_text_emlaey":"ألم يروا إلى الطير مسخرات في جو السماء ما يمسكهن إلا الله إن في ذلك لآيات لقوم يؤمنون","aya_tafseer":"[79] ألم ينظر المشركون إلى الطير مذللات للطيران في الهواء بين السماء والأرض بأمر الله؟ ما يمسكهن عن الوقوع إلا هو سبحانه بما خَلَقه لها من الأجنحة والأذناب، وأقدرها عليه. إن في ذلك التذليل والإمساك لَدلالات لقوم يؤمنون بما يرونه من الأدلة على قدرة الله."},{"id":"1981","jozz":"14","page":"276","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"1","line_end":"3","aya_no":"80","aya_text":"وَٱللَّهُ جَعَلَ لَكُم مِّنۢ بُيُوتِكُمۡ سَكَنٗا وَجَعَلَ لَكُم مِّن جُلُودِ ٱلۡأَنۡعَٰمِ بُيُوتٗا تَسۡتَخِفُّونَهَا يَوۡمَ ظَعۡنِكُمۡ وَيَوۡمَ إِقَامَتِكُمۡ وَمِنۡ أَصۡوَافِهَا وَأَوۡبَارِهَا وَأَشۡعَارِهَآ أَثَٰثٗا وَمَتَٰعًا إِلَىٰ حِينٖ","aya_text_emlaey":"والله جعل لكم من بيوتكم سكنا وجعل لكم من جلود الأنعام بيوتا تستخفونها يوم ظعنكم ويوم إقامتكم ومن أصوافها وأوبارها وأشعارها أثاثا ومتاعا إلى حين","aya_tafseer":"[80] والله سبحانه جعل لكم من بيوتكم راحة واستقراراً مع أهلكم، وأنتم مقيمون في الحضر، وجعل لكم في سفركم خياماً وقباباً من جلود الأنعام، يَخِفُّ عليكم حمْلها وقت تَرْحالكم، ويخف عليكم نَصْبها وقت إقامتكم بعد التَّرْحال، وجعل لكم من أصواف الغنم، وأوبار الإبل، وأشعار المعز أثاثاً لكم من أكسية وألبسة وأغطية وفرش وزينة، تتمتعون بها إلى أجل مسمَّى ووقت معلوم."},{"id":"1982","jozz":"14","page":"276","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"4","line_end":"7","aya_no":"81","aya_text":"وَٱللَّهُ جَعَلَ لَكُم مِّمَّا خَلَقَ ظِلَٰلٗا وَجَعَلَ لَكُم مِّنَ ٱلۡجِبَالِ أَكۡنَٰنٗا وَجَعَلَ لَكُمۡ سَرَٰبِيلَ تَقِيكُمُ ٱلۡحَرَّ وَسَرَٰبِيلَ تَقِيكُم بَأۡسَكُمۡۚ كَذَٰلِكَ يُتِمُّ نِعۡمَتَهُۥ عَلَيۡكُمۡ لَعَلَّكُمۡ تُسۡلِمُونَ","aya_text_emlaey":"والله جعل لكم مما خلق ظلالا وجعل لكم من الجبال أكنانا وجعل لكم سرابيل تقيكم الحر وسرابيل تقيكم بأسكم كذلك يتم نعمته عليكم لعلكم تسلمون","aya_tafseer":"[81] والله جعل لكم ما تستظلُّون به من الأشجار وغيرها، وجعل لكم في الجبال من المغارات والكهوف أماكن تلجؤون إليها عند الحاجة، وجعل لكم ثياباً من القطن والصوف وغيرهما، تحفظكم من الحر والبرد، وجعل لكم من الحديد ما يردُّ عنكم الطعن والأذى في حروبكم، كما أنعم الله عليكم بهذه النعم يتمُّ نعمته عليكم ببيان الدين الحق؛ لتستسلموا لأمر الله وحده، ولا تشركوا به شيئاً في عبادته."},{"id":"1983","jozz":"14","page":"276","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"7","line_end":"8","aya_no":"82","aya_text":"فَإِن تَوَلَّوۡاْ فَإِنَّمَا عَلَيۡكَ ٱلۡبَلَٰغُ ٱلۡمُبِينُ","aya_text_emlaey":"فإن تولوا فإنما عليك البلاغ المبين","aya_tafseer":"[82] فإن أعرضوا عنك -أيها الرسول- بعدما رأوا من الآيات فلا تحزن، فما عليك إلا البلاغ الواضح لما أُرْسِلْتَ به، وأما الهداية فإلينا."},{"id":"1984","jozz":"14","page":"276","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"8","line_end":"9","aya_no":"83","aya_text":"يَعۡرِفُونَ نِعۡمَتَ ٱللَّهِ ثُمَّ يُنكِرُونَهَا وَأَكۡثَرُهُمُ ٱلۡكَٰفِرُونَ","aya_text_emlaey":"يعرفون نعمة الله ثم ينكرونها وأكثرهم الكافرون","aya_tafseer":"[83] يعرف هؤلاء المشركون نعمة الله عليهم بإرسال محمد -صلى الله عليه وسلم- إليهم، ثم يجحدون نبوته، وأكثر قومه الجاحدون لنبوته، لا المقرون بها."},{"id":"1985","jozz":"14","page":"276","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"9","line_end":"10","aya_no":"84","aya_text":"وَيَوۡمَ نَبۡعَثُ مِن كُلِّ أُمَّةٖ شَهِيدٗا ثُمَّ لَا يُؤۡذَنُ لِلَّذِينَ كَفَرُواْ وَلَا هُمۡ يُسۡتَعۡتَبُونَ","aya_text_emlaey":"ويوم نبعث من كل أمة شهيدا ثم لا يؤذن للذين كفروا ولا هم يستعتبون","aya_tafseer":"[84] واذكر لهم -أيها الرسول- ما يكون يوم القيامة، حين نبعث من كل أمة رسولها شاهداً على إيمان مَن آمن منها، وكُفْر مَن كَفَر، ثم لا يُؤذن للذين كفروا بالاعتذار عما وقع منهم، ولا يُطْلب منهم إرضاءُ ربهم بالتوبة والعمل الصالح، فقد مضى أوان ذلك."},{"id":"1986","jozz":"14","page":"276","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"11","line_end":"12","aya_no":"85","aya_text":"وَإِذَا رَءَا ٱلَّذِينَ ظَلَمُواْ ٱلۡعَذَابَ فَلَا يُخَفَّفُ عَنۡهُمۡ وَلَا هُمۡ يُنظَرُونَ","aya_text_emlaey":"وإذا رأى الذين ظلموا العذاب فلا يخفف عنهم ولا هم ينظرون","aya_tafseer":"[85] وإذا شاهد الذين كفروا عذاب الله في الآخرة فلا يخفف عنهم منه شيء، ولا يُمْهلون، ولا يؤخر عذابهم."},{"id":"1987","jozz":"14","page":"276","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"12","line_end":"14","aya_no":"86","aya_text":"وَإِذَا رَءَا ٱلَّذِينَ أَشۡرَكُواْ شُرَكَآءَهُمۡ قَالُواْ رَبَّنَا هَٰٓؤُلَآءِ شُرَكَآؤُنَا ٱلَّذِينَ كُنَّا نَدۡعُواْ مِن دُونِكَۖ فَأَلۡقَوۡاْ إِلَيۡهِمُ ٱلۡقَوۡلَ إِنَّكُمۡ لَكَٰذِبُونَ","aya_text_emlaey":"وإذا رأى الذين أشركوا شركاءهم قالوا ربنا هؤلاء شركاؤنا الذين كنا ندعوا من دونك فألقوا إليهم القول إنكم لكاذبون","aya_tafseer":"[86] وإذا أبصر المشركون يوم القيامة آلهتهم التي عبدوها مع الله، قالوا: ربنا هؤلاء شركاؤنا الذين كنا نعبدهم مِن دونك، فنطقَتِ الآلهة بتكذيب مَن عبدوها، وقالت: إنكم -أيها المشركون- لَكاذبون، حين جعلتمونا شركاء لله وعبدتمونا معه، فلم نأمركم بذلك، ولا زعمنا أننا مستحقون للألوهية، فاللوم عليكم."},{"id":"1988","jozz":"14","page":"276","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"14","line_end":"15","aya_no":"87","aya_text":"وَأَلۡقَوۡاْ إِلَى ٱللَّهِ يَوۡمَئِذٍ ٱلسَّلَمَۖ وَضَلَّ عَنۡهُم مَّا كَانُواْ يَفۡتَرُونَ","aya_text_emlaey":"وألقوا إلى الله يومئذ السلم وضل عنهم ما كانوا يفترون","aya_tafseer":"[87] وأظهر المشركون الاستسلام والخضوع لله يوم القيامة، وغاب عنهم ما كانوا يختلقونه من الأكاذيب، وأن آلهتهم تشفع لهم."},{"id":"1989","jozz":"14","page":"277","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"1","line_end":"2","aya_no":"88","aya_text":"ٱلَّذِينَ كَفَرُواْ وَصَدُّواْ عَن سَبِيلِ ٱللَّهِ زِدۡنَٰهُمۡ عَذَابٗا فَوۡقَ ٱلۡعَذَابِ بِمَا كَانُواْ يُفۡسِدُونَ","aya_text_emlaey":"الذين كفروا وصدوا عن سبيل الله زدناهم عذابا فوق العذاب بما كانوا يفسدون","aya_tafseer":"[88] الذين جحدوا وحدانية الله ونبوتك -أيها الرسول- وكذَّبوك، ومنعوا غيرهم عن الإيمان بالله ورسوله، زدناهم عذاباً على كفرهم وعذاباً على صدِّهم الناس عن اتباع الحق؛ وهذا بسبب تعمُّدهم الإفساد وإضلال العباد بالكفر والمعصية."},{"id":"1990","jozz":"14","page":"277","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"2","line_end":"5","aya_no":"89","aya_text":"وَيَوۡمَ نَبۡعَثُ فِي كُلِّ أُمَّةٖ شَهِيدًا عَلَيۡهِم مِّنۡ أَنفُسِهِمۡۖ وَجِئۡنَا بِكَ شَهِيدًا عَلَىٰ هَٰٓؤُلَآءِۚ وَنَزَّلۡنَا عَلَيۡكَ ٱلۡكِتَٰبَ تِبۡيَٰنٗا لِّكُلِّ شَيۡءٖ وَهُدٗى وَرَحۡمَةٗ وَبُشۡرَىٰ لِلۡمُسۡلِمِينَ","aya_text_emlaey":"ويوم نبعث في كل أمة شهيدا عليهم من أنفسهم وجئنا بك شهيدا على هؤلاء ونـزلنا عليك الكتاب تبيانا لكل شيء وهدى ورحمة وبشرى للمسلمين","aya_tafseer":"[89] واذكر -أيها الرسول- حين نبعث يوم القيامة في كل أمة من الأمم شهيداً عليهم، وهو الرسول الذي بعثه الله إليهم من أنفسهم وبلسانهم، وجئنا بك -أيها الرسول- شهيداً على أمتك أنك بلغت رسالة ربك، وقد نَزَّلْنا عليك القرآن توضيحاً لكل أمر يحتاج إلى بيان، كأحكام الحلال والحرام، والثواب والعقاب، وغير ذلك، وليكون هداية من الضلال، ورحمة لمن صدَّق وعمل به، وبشارة طيبة للمؤمنين بحسن مصيرهم."},{"id":"1991","jozz":"14","page":"277","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"5","line_end":"7","aya_no":"90","aya_text":"۞ إِنَّ ٱللَّهَ يَأۡمُرُ بِٱلۡعَدۡلِ وَٱلۡإِحۡسَٰنِ وَإِيتَآيِٕ ذِي ٱلۡقُرۡبَىٰ وَيَنۡهَىٰ عَنِ ٱلۡفَحۡشَآءِ وَٱلۡمُنكَرِ وَٱلۡبَغۡيِۚ يَعِظُكُمۡ لَعَلَّكُمۡ تَذَكَّرُونَ","aya_text_emlaey":"إن الله يأمر بالعدل والإحسان وإيتاء ذي القربى وينهى عن الفحشاء والمنكر والبغي يعظكم لعلكم تذكرون","aya_tafseer":"[90] إن الله سبحانه وتعالى يأمر عباده في هذا القرآن بالعدل والإنصاف في حقه بتوحيده وعدم الإشراك به، وفي حق عباده بإعطاء كل ذي حق حقه، ويأمر بالإحسان في حقه بعبادته وأداء فرائضه على الوجه المشروع، وإلى الخلق في الأقوال والأفعال، ويأمر بإعطاء ذوي القرابة ما به صلتهم وبرُّهم، وينهى عن كل ما قَبُحَ قولاً أو عملاً، وعما ينكره الشرع ولا يرضاه من الكفر والمعاصي، وعن ظلم الناس والتعدي عليهم، والله -بهذا الأمر وهذا النهي- يَعِظكم ويذكِّركم العواقب؛ لكي تتذكروا أوامر الله وتنتفعوا بها."},{"id":"1992","jozz":"14","page":"277","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"8","line_end":"10","aya_no":"91","aya_text":"وَأَوۡفُواْ بِعَهۡدِ ٱللَّهِ إِذَا عَٰهَدتُّمۡ وَلَا تَنقُضُواْ ٱلۡأَيۡمَٰنَ بَعۡدَ تَوۡكِيدِهَا وَقَدۡ جَعَلۡتُمُ ٱللَّهَ عَلَيۡكُمۡ كَفِيلًاۚ إِنَّ ٱللَّهَ يَعۡلَمُ مَا تَفۡعَلُونَ","aya_text_emlaey":"وأوفوا بعهد الله إذا عاهدتم ولا تنقضوا الأيمان بعد توكيدها وقد جعلتم الله عليكم كفيلا إن الله يعلم ما تفعلون","aya_tafseer":"[91] والتزموا الوفاء بكل عهد أوجبتموه على أنفسكم بينكم وبين الله -تعالى-، أو بينكم وبين الناس فيما لا يخالف كتاب الله وسنة نبيه، ولا ترجعوا في الأيمان بعد أن أكَّدْتموها، وقد جعلتم الله عليكم كفيلاً وضامناً حين عاهدتموه. إن الله يعلم ما تفعلونه، وسيجزيكم عليه."},{"id":"1993","jozz":"14","page":"277","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"10","line_end":"13","aya_no":"92","aya_text":"وَلَا تَكُونُواْ كَٱلَّتِي نَقَضَتۡ غَزۡلَهَا مِنۢ بَعۡدِ قُوَّةٍ أَنكَٰثٗا تَتَّخِذُونَ أَيۡمَٰنَكُمۡ دَخَلَۢا بَيۡنَكُمۡ أَن تَكُونَ أُمَّةٌ هِيَ أَرۡبَىٰ مِنۡ أُمَّةٍۚ إِنَّمَا يَبۡلُوكُمُ ٱللَّهُ بِهِۦۚ وَلَيُبَيِّنَنَّ لَكُمۡ يَوۡمَ ٱلۡقِيَٰمَةِ مَا كُنتُمۡ فِيهِ تَخۡتَلِفُونَ","aya_text_emlaey":"ولا تكونوا كالتي نقضت غزلها من بعد قوة أنكاثا تتخذون أيمانكم دخلا بينكم أن تكون أمة هي أربى من أمة إنما يبلوكم الله به وليبينن لكم يوم القيامة ما كنتم فيه تختلفون","aya_tafseer":"[92] ولا ترجعوا في عهودكم، فيكون مَثَلكم مثل امرأة غزلت غَزْلاً وأَحْكَمَتْه، ثم نقضته؛ تجعلون أيمانكم التي حلفتموها عند التعاهد خديعة لمن عاهدتموه، وتنقضون عهدكم إذا وجدتم جماعة أكثر مالاً ومنفعة من الذين عاهدتموهم، إنما يختبركم الله بما أمركم به من الوفاء بالعهود وما نهاكم عنه مِن نقضها، ولَيُبَيِّنَنَّ لكم يوم القيامة ما كنتم فيه تختلفون في الدنيا من الإيمان بالله ونبوة محمد -صلى الله عليه وسلم-."},{"id":"1994","jozz":"14","page":"277","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"14","line_end":"15","aya_no":"93","aya_text":"وَلَوۡ شَآءَ ٱللَّهُ لَجَعَلَكُمۡ أُمَّةٗ وَٰحِدَةٗ وَلَٰكِن يُضِلُّ مَن يَشَآءُ وَيَهۡدِي مَن يَشَآءُۚ وَلَتُسۡـَٔلُنَّ عَمَّا كُنتُمۡ تَعۡمَلُونَ","aya_text_emlaey":"ولو شاء الله لجعلكم أمة واحدة ولكن يضل من يشاء ويهدي من يشاء ولتسألن عما كنتم تعملون","aya_tafseer":"[93] ولو شاء الله لوفَّقكم كلكم، فجعلكم على ملة واحدة، وهي الإسلام والإيمان، وألزمكم به، ولكنه سبحانه يُضِلُّ مَن يشاء ممن علم منه إيثار الضلال، فلا يهديه؛ عدلاً منه، ويهدي مَن يشاء مِمَّن علم منه إيثار الحق، فيوفقه؛ فضلاً منه، وليسألنَّكم الله جميعاً يوم القيامة عما كنتم تعملون في الدنيا فيما أمركم به، ونهاكم عنه، وسيجازيكم على ذلك."},{"id":"1995","jozz":"14","page":"278","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"1","line_end":"3","aya_no":"94","aya_text":"وَلَا تَتَّخِذُوٓاْ أَيۡمَٰنَكُمۡ دَخَلَۢا بَيۡنَكُمۡ فَتَزِلَّ قَدَمُۢ بَعۡدَ ثُبُوتِهَا وَتَذُوقُواْ ٱلسُّوٓءَ بِمَا صَدَدتُّمۡ عَن سَبِيلِ ٱللَّهِ وَلَكُمۡ عَذَابٌ عَظِيمٞ","aya_text_emlaey":"ولا تتخذوا أيمانكم دخلا بينكم فتزل قدم بعد ثبوتها وتذوقوا السوء بما صددتم عن سبيل الله ولكم عذاب عظيم","aya_tafseer":"[94] ولا تجعلوا من الأيمان التي تحلفونها خديعة لمن حلفتم لهم، فتهلكوا بعد أن كنتم آمنين، كمن زلقت قدمه بعد ثبوتها، وتذوقوا ما يسوءكم من العذاب في الدنيا؛ بما تسببتم فيه مِن مَنْع غيركم عن هذا الدين لما رأوه منكم من الغدر، ولكم في الآخرة عذاب عظيم."},{"id":"1996","jozz":"14","page":"278","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"3","line_end":"4","aya_no":"95","aya_text":"وَلَا تَشۡتَرُواْ بِعَهۡدِ ٱللَّهِ ثَمَنٗا قَلِيلًاۚ إِنَّمَا عِندَ ٱللَّهِ هُوَ خَيۡرٞ لَّكُمۡ إِن كُنتُمۡ تَعۡلَمُونَ","aya_text_emlaey":"ولا تشتروا بعهد الله ثمنا قليلا إنما عند الله هو خير لكم إن كنتم تعلمون","aya_tafseer":"[95] ولا تنقضوا عهد الله؛ لتستبدلوا مكانه عرضاً قليلاً من متاع الدنيا، إن ما عند الله من الثواب على الوفاء أفضل لكم من هذا الثمن القليل، إن كنتم من أهل العلم، فتدبَّروا الفرق بين خيْرَي الدنيا والآخرة."},{"id":"1997","jozz":"14","page":"278","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"4","line_end":"6","aya_no":"96","aya_text":"مَا عِندَكُمۡ يَنفَدُ وَمَا عِندَ ٱللَّهِ بَاقٖۗ وَلَنَجۡزِيَنَّ ٱلَّذِينَ صَبَرُوٓاْ أَجۡرَهُم بِأَحۡسَنِ مَا كَانُواْ يَعۡمَلُونَ","aya_text_emlaey":"ما عندكم ينفد وما عند الله باق ولنجزين الذين صبروا أجرهم بأحسن ما كانوا يعملون","aya_tafseer":"[96] ما عندكم من حطام الدنيا يذهب، وما عند الله لكم من الرزق والثواب لا يزول. ولَنُثِيبنَّ الذين تحمَّلوا مشاق التكاليف -ومنها الوفاء بالعهد- ثوابهم بأحسن أعمالهم، فنعطيهم على أدناها، كما نعطيهم على أعلاها تفضُّلاً."},{"id":"1998","jozz":"14","page":"278","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"6","line_end":"8","aya_no":"97","aya_text":"مَنۡ عَمِلَ صَٰلِحٗا مِّن ذَكَرٍ أَوۡ أُنثَىٰ وَهُوَ مُؤۡمِنٞ فَلَنُحۡيِيَنَّهُۥ حَيَوٰةٗ طَيِّبَةٗۖ وَلَنَجۡزِيَنَّهُمۡ أَجۡرَهُم بِأَحۡسَنِ مَا كَانُواْ يَعۡمَلُونَ","aya_text_emlaey":"من عمل صالحا من ذكر أو أنثى وهو مؤمن فلنحيينه حياة طيبة ولنجزينهم أجرهم بأحسن ما كانوا يعملون","aya_tafseer":"[97] مَن عمل عملاً صالحاً، ذكراً كان أم أنثى، وهو مؤمن بالله ورسوله، فلنحيينه في الدنيا حياة سعيدة مطمئنة، ولو كان قليل المال، ولنجزينَّهم في الآخرة ثوابهم بأحسن ما عملوا في الدنيا."},{"id":"1999","jozz":"14","page":"278","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"9","line_end":"9","aya_no":"98","aya_text":"فَإِذَا قَرَأۡتَ ٱلۡقُرۡءَانَ فَٱسۡتَعِذۡ بِٱللَّهِ مِنَ ٱلشَّيۡطَٰنِ ٱلرَّجِيمِ","aya_text_emlaey":"فإذا قرأت القرآن فاستعذ بالله من الشيطان الرجيم","aya_tafseer":"[98] فإذا أردت -أيها المؤمن- أن تقرأ شيئاً من القرآن فاستعذ بالله مِن شرِّ الشيطان المطرود من رحمة الله قائلاً: أعوذ بالله من الشيطان الرجيم."},{"id":"2000","jozz":"14","page":"278","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"10","line_end":"11","aya_no":"99","aya_text":"إِنَّهُۥ لَيۡسَ لَهُۥ سُلۡطَٰنٌ عَلَى ٱلَّذِينَ ءَامَنُواْ وَعَلَىٰ رَبِّهِمۡ يَتَوَكَّلُونَ","aya_text_emlaey":"إنه ليس له سلطان على الذين آمنوا وعلى ربهم يتوكلون","aya_tafseer":"[99] إن الشيطان ليس له تسلُّطٌ على المؤمنين بالله ورسوله، وعلى ربهم وحده يعتمدون"},{"id":"2001","jozz":"14","page":"278","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"11","line_end":"12","aya_no":"100","aya_text":"إِنَّمَا سُلۡطَٰنُهُۥ عَلَى ٱلَّذِينَ يَتَوَلَّوۡنَهُۥ وَٱلَّذِينَ هُم بِهِۦ مُشۡرِكُونَ","aya_text_emlaey":"إنما سلطانه على الذين يتولونه والذين هم به مشركون","aya_tafseer":"[100] إنما تسلُّطه على الذين جعلوه مُعيناً لهم وأطاعوه، والذين هم -بسبب طاعته- مشركون بالله تعالى."},{"id":"2002","jozz":"14","page":"278","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"12","line_end":"14","aya_no":"101","aya_text":"وَإِذَا بَدَّلۡنَآ ءَايَةٗ مَّكَانَ ءَايَةٖ وَٱللَّهُ أَعۡلَمُ بِمَا يُنَزِّلُ قَالُوٓاْ إِنَّمَآ أَنتَ مُفۡتَرِۭۚ بَلۡ أَكۡثَرُهُمۡ لَا يَعۡلَمُونَ","aya_text_emlaey":"وإذا بدلنا آية مكان آية والله أعلم بما ينـزل قالوا إنما أنت مفتر بل أكثرهم لا يعلمون","aya_tafseer":"[101] وإذا بدَّلنا آية بآية أخرى، والله الخالق أعلم بمصلحة خَلْقه بما ينزله من الأحكام في الأوقات المختلفة، قال الكفار: إنما أنت -يا محمد- كاذب مختَلِق على الله ما لم يَقُلْه. ومحمد -صلى الله عليه وسلم- ليس كما يزعمون. بل أكثرهم لا عِلْم لهم بربهم ولا بشرعه وأحكامه."},{"id":"2003","jozz":"14","page":"278","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"14","line_end":"15","aya_no":"102","aya_text":"قُلۡ نَزَّلَهُۥ رُوحُ ٱلۡقُدُسِ مِن رَّبِّكَ بِٱلۡحَقِّ لِيُثَبِّتَ ٱلَّذِينَ ءَامَنُواْ وَهُدٗى وَبُشۡرَىٰ لِلۡمُسۡلِمِينَ","aya_text_emlaey":"قل نـزله روح القدس من ربك بالحق ليثبت الذين آمنوا وهدى وبشرى للمسلمين","aya_tafseer":"[102] قل لهم -أيها الرسول-: ليس القرآن مختلَقاً مِن عندي، بل نَزَّله جبريل مِن ربك بالصدق والعدل؛ تثبيتاً للمؤمنين، وهداية من الضلال، وبشارة طيبة لمن أسلموا وخضعوا لله رب العالمين."},{"id":"2004","jozz":"14","page":"279","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"1","line_end":"2","aya_no":"103","aya_text":"وَلَقَدۡ نَعۡلَمُ أَنَّهُمۡ يَقُولُونَ إِنَّمَا يُعَلِّمُهُۥ بَشَرٞۗ لِّسَانُ ٱلَّذِي يُلۡحِدُونَ إِلَيۡهِ أَعۡجَمِيّٞ وَهَٰذَا لِسَانٌ عَرَبِيّٞ مُّبِينٌ","aya_text_emlaey":"ولقد نعلم أنهم يقولون إنما يعلمه بشر لسان الذي يلحدون إليه أعجمي وهذا لسان عربي مبين","aya_tafseer":"[103] ولقد نعلم أن المشركين يقولون: إن النبي يتلقى القرآن مِن بشر مِن بني آدم. كذبوا؛ فإن لسان الذي نسبوا إليه تعليم النبي -صلى الله عليه وسلم- أعجمي لا يُفصح، والقرآن عربي غاية في الوضوح والبيان."},{"id":"2005","jozz":"14","page":"279","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"3","line_end":"4","aya_no":"104","aya_text":"إِنَّ ٱلَّذِينَ لَا يُؤۡمِنُونَ بِـَٔايَٰتِ ٱللَّهِ لَا يَهۡدِيهِمُ ٱللَّهُ وَلَهُمۡ عَذَابٌ أَلِيمٌ","aya_text_emlaey":"إن الذين لا يؤمنون بآيات الله لا يهديهم الله ولهم عذاب أليم","aya_tafseer":"[104] إن الكفار الذين لا يصدقون بالقرآن لا يوفقهم الله لإصابة الحق، ولهم في الآخرة عذاب مؤلم موجع."},{"id":"2006","jozz":"14","page":"279","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"4","line_end":"5","aya_no":"105","aya_text":"إِنَّمَا يَفۡتَرِي ٱلۡكَذِبَ ٱلَّذِينَ لَا يُؤۡمِنُونَ بِـَٔايَٰتِ ٱللَّهِۖ وَأُوْلَٰٓئِكَ هُمُ ٱلۡكَٰذِبُونَ","aya_text_emlaey":"إنما يفتري الكذب الذين لا يؤمنون بآيات الله وأولئك هم الكاذبون","aya_tafseer":"[105] إنما يختلق الكذبَ مَن لا يؤمن بالله وآياته، وأولئك هم الكاذبون في قولهم ذلك. أما محمد -صلى الله عليه وسلم- المؤمن بربه الخاضعُ له فمحال أن يكذب على الله، ويقولَ عليه ما لم يقله."},{"id":"2007","jozz":"14","page":"279","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"6","line_end":"8","aya_no":"106","aya_text":"مَن كَفَرَ بِٱللَّهِ مِنۢ بَعۡدِ إِيمَٰنِهِۦٓ إِلَّا مَنۡ أُكۡرِهَ وَقَلۡبُهُۥ مُطۡمَئِنُّۢ بِٱلۡإِيمَٰنِ وَلَٰكِن مَّن شَرَحَ بِٱلۡكُفۡرِ صَدۡرٗا فَعَلَيۡهِمۡ غَضَبٞ مِّنَ ٱللَّهِ وَلَهُمۡ عَذَابٌ عَظِيمٞ","aya_text_emlaey":"من كفر بالله من بعد إيمانه إلا من أكره وقلبه مطمئن بالإيمان ولكن من شرح بالكفر صدرا فعليهم غضب من الله ولهم عذاب عظيم","aya_tafseer":"[106] إنما يفتري الكذب مَن نطق بكلمة الكفر وارتدَّ بعد إيمانه، فعليهم غضبٌ من الله، إلا مَن أُرغم على النطق بالكفر، فنطق به خوفاً من الهلاك، وقلبه ثابت على الإيمان، فلا لوم عليه، لكن مَن نطق بالكفر واطمأن قلبه إليه، فعليهم غضب شديد من الله، ولهم عذاب عظيم؛"},{"id":"2008","jozz":"14","page":"279","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"9","line_end":"10","aya_no":"107","aya_text":"ذَٰلِكَ بِأَنَّهُمُ ٱسۡتَحَبُّواْ ٱلۡحَيَوٰةَ ٱلدُّنۡيَا عَلَى ٱلۡأٓخِرَةِ وَأَنَّ ٱللَّهَ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلۡكَٰفِرِينَ","aya_text_emlaey":"ذلك بأنهم استحبوا الحياة الدنيا على الآخرة وأن الله لا يهدي القوم الكافرين","aya_tafseer":"[107] وذلك بسبب إيثارهم الدنيا وزينتَها، وتفضيلِهم إياها على الآخرة وثوابِها، وأن الله لا يوفِّق الكافرين للحق والصواب."},{"id":"2009","jozz":"14","page":"279","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"11","line_end":"12","aya_no":"108","aya_text":"أُوْلَٰٓئِكَ ٱلَّذِينَ طَبَعَ ٱللَّهُ عَلَىٰ قُلُوبِهِمۡ وَسَمۡعِهِمۡ وَأَبۡصَٰرِهِمۡۖ وَأُوْلَٰٓئِكَ هُمُ ٱلۡغَٰفِلُونَ","aya_text_emlaey":"أولئك الذين طبع الله على قلوبهم وسمعهم وأبصارهم وأولئك هم الغافلون","aya_tafseer":"[108] أولئك هم الذين ختم الله على قلوبهم بالكفر وإيثار الدنيا على الآخرة، فلا يصل إليها نور الهداية، وأصمَّ سمعهم عن آيات الله فلا يسمعونها سماع تدبُّر، وأعمى أبصارهم فلا يرون البراهين الدالة على ألوهية الله، وأولئك هم الغافلون عمَّا أعدَّ الله لهم من العذاب."},{"id":"2010","jozz":"14","page":"279","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"12","line_end":"13","aya_no":"109","aya_text":"لَا جَرَمَ أَنَّهُمۡ فِي ٱلۡأٓخِرَةِ هُمُ ٱلۡخَٰسِرُونَ","aya_text_emlaey":"لا جرم أنهم في الآخرة هم الخاسرون","aya_tafseer":"[109] حقّاً أنهم في الآخرة هم الخاسرون الهالكون، الذين صرفوا حياتهم إلى ما فيه عذابهم وهلاكهم."},{"id":"2011","jozz":"14","page":"279","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"13","line_end":"15","aya_no":"110","aya_text":"ثُمَّ إِنَّ رَبَّكَ لِلَّذِينَ هَاجَرُواْ مِنۢ بَعۡدِ مَا فُتِنُواْ ثُمَّ جَٰهَدُواْ وَصَبَرُوٓاْ إِنَّ رَبَّكَ مِنۢ بَعۡدِهَا لَغَفُورٞ رَّحِيمٞ","aya_text_emlaey":"ثم إن ربك للذين هاجروا من بعد ما فتنوا ثم جاهدوا وصبروا إن ربك من بعدها لغفور رحيم","aya_tafseer":"[110] ثم إن ربك للمستضعفين في «مكة» الذين عذَّبهم المشركون، حتى وافقوهم على ما هم عليه ظاهراً، ففتنوهم بالتلفظ بما يرضيهم، وقلوبهم مطمئنة بالإيمان، ولمَّا أمكنهم الخلاص هاجروا إلى «المدينة»، ثم جاهدوا في سبيل الله، وصبروا على مشاق التكاليف، إن ربك -من بعد توبتهم- لَغفور لهم، رحيم بهم."},{"id":"2012","jozz":"14","page":"280","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"1","line_end":"2","aya_no":"111","aya_text":"۞ يَوۡمَ تَأۡتِي كُلُّ نَفۡسٖ تُجَٰدِلُ عَن نَّفۡسِهَا وَتُوَفَّىٰ كُلُّ نَفۡسٖ مَّا عَمِلَتۡ وَهُمۡ لَا يُظۡلَمُونَ","aya_text_emlaey":"يوم تأتي كل نفس تجادل عن نفسها وتوفى كل نفس ما عملت وهم لا يظلمون","aya_tafseer":"[111] وذكرهم -أيها الرسول- بيوم القيامة حين تأتي كل نفس تخاصم عن ذاتها، وتعتذر بكل المعاذير، ويوفي الله كل نفس جزاء ما عَمِلَتْه مِن غير ظلم لها، فلا يزيدهم في العقاب، ولا ينقصهم من الثواب."},{"id":"2013","jozz":"14","page":"280","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"2","line_end":"5","aya_no":"112","aya_text":"وَضَرَبَ ٱللَّهُ مَثَلٗا قَرۡيَةٗ كَانَتۡ ءَامِنَةٗ مُّطۡمَئِنَّةٗ يَأۡتِيهَا رِزۡقُهَا رَغَدٗا مِّن كُلِّ مَكَانٖ فَكَفَرَتۡ بِأَنۡعُمِ ٱللَّهِ فَأَذَٰقَهَا ٱللَّهُ لِبَاسَ ٱلۡجُوعِ وَٱلۡخَوۡفِ بِمَا كَانُواْ يَصۡنَعُونَ","aya_text_emlaey":"وضرب الله مثلا قرية كانت آمنة مطمئنة يأتيها رزقها رغدا من كل مكان فكفرت بأنعم الله فأذاقها الله لباس الجوع والخوف بما كانوا يصنعون","aya_tafseer":"[112] وضرب الله مثلاً بلدة «مكة» كانت في أمان من الاعتداء، واطمئنان مِن ضيق العيش، يأتيها رزقها هنيئاً سهلاً من كل جهة، فجحد أهلُها نِعَمَ الله عليهم، وأشركوا به، ولم يشكروا له، فعاقبهم الله بالجوع، والخوف من سرايا رسول الله -صلى الله عليه وسلم- وجيوشه، التي كانت تخيفهم؛ وذلك بسبب كفرهم وصنيعهم الباطل."},{"id":"2014","jozz":"14","page":"280","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"5","line_end":"6","aya_no":"113","aya_text":"وَلَقَدۡ جَآءَهُمۡ رَسُولٞ مِّنۡهُمۡ فَكَذَّبُوهُ فَأَخَذَهُمُ ٱلۡعَذَابُ وَهُمۡ ظَٰلِمُونَ","aya_text_emlaey":"ولقد جاءهم رسول منهم فكذبوه فأخذهم العذاب وهم ظالمون","aya_tafseer":"[113] ولقد أرسل الله إلى أهل «مكة» رسولاً منهم، هو النبي محمد -صلى الله عليه وسلم-، يعرفون نسبه وصدقه وأمانته، فلم يقبلوا ما جاءهم به، ولم يصدقوه، فأخذهم العذاب من الشدائد والجوع والخوف، وقَتْلِ عظمائهم في «بدر»، وهم ظالمون لأنفسهم بالشرك بالله، والصدِّ عن سبيله."},{"id":"2015","jozz":"14","page":"280","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"7","line_end":"8","aya_no":"114","aya_text":"فَكُلُواْ مِمَّا رَزَقَكُمُ ٱللَّهُ حَلَٰلٗا طَيِّبٗا وَٱشۡكُرُواْ نِعۡمَتَ ٱللَّهِ إِن كُنتُمۡ إِيَّاهُ تَعۡبُدُونَ","aya_text_emlaey":"فكلوا مما رزقكم الله حلالا طيبا واشكروا نعمة الله إن كنتم إياه تعبدون","aya_tafseer":"[114] فكلوا -أيها المؤمنون- مما رزقكم الله، وجعله لكم حلالاً مستطاباً، واشكروا نعمة الله عليكم بالاعتراف بها وصَرْفها في طاعة الله، إن كنتم حقّاً منقادين لأمره سامعين مطيعين له، تعبدونه وحده لا شريك له."},{"id":"2016","jozz":"14","page":"280","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"8","line_end":"11","aya_no":"115","aya_text":"إِنَّمَا حَرَّمَ عَلَيۡكُمُ ٱلۡمَيۡتَةَ وَٱلدَّمَ وَلَحۡمَ ٱلۡخِنزِيرِ وَمَآ أُهِلَّ لِغَيۡرِ ٱللَّهِ بِهِۦۖ فَمَنِ ٱضۡطُرَّ غَيۡرَ بَاغٖ وَلَا عَادٖ فَإِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٞ","aya_text_emlaey":"إنما حرم عليكم الميتة والدم ولحم الخنـزير وما أهل لغير الله به فمن اضطر غير باغ ولا عاد فإن الله غفور رحيم","aya_tafseer":"[115] إنما حرَّم الله عليكم الميتة من الحيوان، والدم المسفوح من الذبيح عند ذبحه، ولحم الخنزير، وما ذبح لغير الله، لكن مَن ألجأته ضرورة الخوف من الموت إلى أَكْلِ شيء مِن هذه المحرمات وهو غير ظالم، ولا متجاوزٍ حدَّ الضرورة، فإن الله غفور له، رحيم به، لا يعاقبه على ما فعل."},{"id":"2017","jozz":"14","page":"280","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"11","line_end":"13","aya_no":"116","aya_text":"وَلَا تَقُولُواْ لِمَا تَصِفُ أَلۡسِنَتُكُمُ ٱلۡكَذِبَ هَٰذَا حَلَٰلٞ وَهَٰذَا حَرَامٞ لِّتَفۡتَرُواْ عَلَى ٱللَّهِ ٱلۡكَذِبَۚ إِنَّ ٱلَّذِينَ يَفۡتَرُونَ عَلَى ٱللَّهِ ٱلۡكَذِبَ لَا يُفۡلِحُونَ","aya_text_emlaey":"ولا تقولوا لما تصف ألسنتكم الكذب هذا حلال وهذا حرام لتفتروا على الله الكذب إن الذين يفترون على الله الكذب لا يفلحون","aya_tafseer":"[116] ولا تقولوا -أيها المشركون- للكذب الذي تصفه ألسنتكم: هذا حلال لِمَا حَرَّمه الله، وهذا حرام لِمَا أحَلَّه الله؛ لتختلقوا على الله الكذب بنسبة التحليل والتحريم إليه، إن الذين يختلقون على الله الكذب لا يفوزون بخير في الدنيا ولا في الآخرة."},{"id":"2018","jozz":"14","page":"280","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"13","line_end":"14","aya_no":"117","aya_text":"مَتَٰعٞ قَلِيلٞ وَلَهُمۡ عَذَابٌ أَلِيمٞ","aya_text_emlaey":"متاع قليل ولهم عذاب أليم","aya_tafseer":"[117] متاعهم في الدنيا متاع زائل ضئيل، ولهم في الآخرة عذاب موجع."},{"id":"2019","jozz":"14","page":"280","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"14","line_end":"15","aya_no":"118","aya_text":"وَعَلَى ٱلَّذِينَ هَادُواْ حَرَّمۡنَا مَا قَصَصۡنَا عَلَيۡكَ مِن قَبۡلُۖ وَمَا ظَلَمۡنَٰهُمۡ وَلَٰكِن كَانُوٓاْ أَنفُسَهُمۡ يَظۡلِمُونَ","aya_text_emlaey":"وعلى الذين هادوا حرمنا ما قصصنا عليك من قبل وما ظلمناهم ولكن كانوا أنفسهم يظلمون","aya_tafseer":"[118] وعلى اليهود حَرَّمنا ما أخبرناك به -أيها الرسول- مِن قبل، وهو كل ذي ظُفُر، وشحوم البقر والغنم، إلا ما حَمَلَتْه ظهورها أو أمعاؤها أو كان مختلطاً بعظم، وما ظلمناهم بتحريم ذلك عليهم، ولكن كانوا ظالمين لأنفسهم بالكفر والبغي، فاستحقوا التحريم عقوبة لهم."},{"id":"2020","jozz":"14","page":"281","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"1","line_end":"2","aya_no":"119","aya_text":"ثُمَّ إِنَّ رَبَّكَ لِلَّذِينَ عَمِلُواْ ٱلسُّوٓءَ بِجَهَٰلَةٖ ثُمَّ تَابُواْ مِنۢ بَعۡدِ ذَٰلِكَ وَأَصۡلَحُوٓاْ إِنَّ رَبَّكَ مِنۢ بَعۡدِهَا لَغَفُورٞ رَّحِيمٌ","aya_text_emlaey":"ثم إن ربك للذين عملوا السوء بجهالة ثم تابوا من بعد ذلك وأصلحوا إن ربك من بعدها لغفور رحيم","aya_tafseer":"[119] ثم إن ربك للذين فعلوا المعاصي في حال جهلهم لعاقبتها وإيجابها لسخط الله، وبغفلة منهم أو ضعف يقين -فكل عاص لله -مخطئاً أو متعمداً- فهو جاهل بهذا الاعتبار وإن كان عالماً بالتحريم-، ثم رجعوا إلى الله عمَّا كانوا عليه من الذنوب، وأصلحوا نفوسهم وأعمالهم، إن ربك -مِن بعد توبتهم وإصلاحهم- لَغفور لهم، رحيم بهم."},{"id":"2021","jozz":"14","page":"281","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"2","line_end":"3","aya_no":"120","aya_text":"إِنَّ إِبۡرَٰهِيمَ كَانَ أُمَّةٗ قَانِتٗا لِّلَّهِ حَنِيفٗا وَلَمۡ يَكُ مِنَ ٱلۡمُشۡرِكِينَ","aya_text_emlaey":"إن إبراهيم كان أمة قانتا لله حنيفا ولم يك من المشركين","aya_tafseer":"[120] إن إبراهيم كان إماماً في الخير، وكان طائعاً خاضعاً لله، لا يميل عن دين الإسلام موحِّداً لله غير مشرك به"},{"id":"2022","jozz":"14","page":"281","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"4","line_end":"4","aya_no":"121","aya_text":"شَاكِرٗا لِّأَنۡعُمِهِۚ ٱجۡتَبَىٰهُ وَهَدَىٰهُ إِلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ","aya_text_emlaey":"شاكرا لأنعمه اجتباه وهداه إلى صراط مستقيم","aya_tafseer":"[121] وكان شاكراً لنعم الله عليه، اختاره الله لرسالته، وأرشده إلى الطريق المستقيم، وهو الإسلام،"},{"id":"2023","jozz":"14","page":"281","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"5","line_end":"5","aya_no":"122","aya_text":"وَءَاتَيۡنَٰهُ فِي ٱلدُّنۡيَا حَسَنَةٗۖ وَإِنَّهُۥ فِي ٱلۡأٓخِرَةِ لَمِنَ ٱلصَّٰلِحِينَ","aya_text_emlaey":"وآتيناه في الدنيا حسنة وإنه في الآخرة لمن الصالحين","aya_tafseer":"[122] ، وآتيناه في الدنيا نعمة حسنة من الثناء عليه في الآخِرين والقدوة به، والولد الصالح، وإنه عند الله في الآخرة لمن الصالحين أصحاب المنازل العالية."},{"id":"2024","jozz":"14","page":"281","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"6","line_end":"7","aya_no":"123","aya_text":"ثُمَّ أَوۡحَيۡنَآ إِلَيۡكَ أَنِ ٱتَّبِعۡ مِلَّةَ إِبۡرَٰهِيمَ حَنِيفٗاۖ وَمَا كَانَ مِنَ ٱلۡمُشۡرِكِينَ","aya_text_emlaey":"ثم أوحينا إليك أن اتبع ملة إبراهيم حنيفا وما كان من المشركين","aya_tafseer":"[123] ثم أوحينا إليك -أيها الرسول- أن اتبع دين الإسلام كما اتبعه إبراهيم، وأن استقم عليه، ولا تَحِدْ عنه، فإن إبراهيم لم يكن من المشركين مع الله غيره."},{"id":"2025","jozz":"14","page":"281","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"7","line_end":"9","aya_no":"124","aya_text":"إِنَّمَا جُعِلَ ٱلسَّبۡتُ عَلَى ٱلَّذِينَ ٱخۡتَلَفُواْ فِيهِۚ وَإِنَّ رَبَّكَ لَيَحۡكُمُ بَيۡنَهُمۡ يَوۡمَ ٱلۡقِيَٰمَةِ فِيمَا كَانُواْ فِيهِ يَخۡتَلِفُونَ","aya_text_emlaey":"إنما جعل السبت على الذين اختلفوا فيه وإن ربك ليحكم بينهم يوم القيامة فيما كانوا فيه يختلفون","aya_tafseer":"[124] إنما جعل الله تعظيم يوم السبت بالتفرغ للعبادة فيه على اليهود الذين اختلفوا فيه على نبيهم، واختاروه بدل يوم الجمعة الذي أُمِروا بتعظيمه. وإن ربك -أيها الرسول- لَيحكم بين المختلفين يوم القيامة فيما اختلفوا فيه على نبيهم، ويجازي كُلّاً بما يستحقه."},{"id":"2026","jozz":"14","page":"281","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"9","line_end":"11","aya_no":"125","aya_text":"ٱدۡعُ إِلَىٰ سَبِيلِ رَبِّكَ بِٱلۡحِكۡمَةِ وَٱلۡمَوۡعِظَةِ ٱلۡحَسَنَةِۖ وَجَٰدِلۡهُم بِٱلَّتِي هِيَ أَحۡسَنُۚ إِنَّ رَبَّكَ هُوَ أَعۡلَمُ بِمَن ضَلَّ عَن سَبِيلِهِۦ وَهُوَ أَعۡلَمُ بِٱلۡمُهۡتَدِينَ","aya_text_emlaey":"ادع إلى سبيل ربك بالحكمة والموعظة الحسنة وجادلهم بالتي هي أحسن إن ربك هو أعلم بمن ضل عن سبيله وهو أعلم بالمهتدين","aya_tafseer":"[125] ادعُ -أيها الرسول- أنت ومَنِ اتبعك إلى دين ربك وطريقه المستقيم، بالطريقة الحكيمة التي أوحاها الله إليك في الكتاب والسنة، وخاطِب الناس بالأسلوب المناسب لهم، وانصح لهم نصحاً حسناً، يرغبهم في الخير، وينفرهم من الشر، وجادلهم بأحسن طرق المجادلة من الرفق واللين. فما عليك إلا البلاغ، وقد بلَّغْتَ، أما هدايتهم فعلى الله وحده، فهو أعلم بمن ضلَّ عن سبيله، وهو أعلم بالمهتدين."},{"id":"2027","jozz":"14","page":"281","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"12","line_end":"13","aya_no":"126","aya_text":"وَإِنۡ عَاقَبۡتُمۡ فَعَاقِبُواْ بِمِثۡلِ مَا عُوقِبۡتُم بِهِۦۖ وَلَئِن صَبَرۡتُمۡ لَهُوَ خَيۡرٞ لِّلصَّٰبِرِينَ","aya_text_emlaey":"وإن عاقبتم فعاقبوا بمثل ما عوقبتم به ولئن صبرتم لهو خير للصابرين","aya_tafseer":"[126] وإن أردتم -أيها المؤمنون- القصاص ممن اعتدوا عليكم، فلا تزيدوا عما فعلوه بكم، ولئن صبرتم لهو خير لكم في الدنيا بالنصر، وفي الآخرة بالأجر العظيم."},{"id":"2028","jozz":"14","page":"281","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"13","line_end":"14","aya_no":"127","aya_text":"وَٱصۡبِرۡ وَمَا صَبۡرُكَ إِلَّا بِٱللَّهِۚ وَلَا تَحۡزَنۡ عَلَيۡهِمۡ وَلَا تَكُ فِي ضَيۡقٖ مِّمَّا يَمۡكُرُونَ","aya_text_emlaey":"واصبر وما صبرك إلا بالله ولا تحزن عليهم ولا تك في ضيق مما يمكرون","aya_tafseer":"[127] واصبر -أيها الرسول- على ما أصابك مِن أذى في الله حتى يأتيك الفرج، وما صبرك إلا بالله، فهو الذي يعينك عليه ويثبتك، ولا تحزن على مَن خالفك ولم يستجب لدعوتك، ولا تغتم مِن مكرهم وكيدهم؛ فإن ذلك عائد عليهم بالشر والوبال."},{"id":"2029","jozz":"14","page":"281","sura_no":"16","sura_name_en":"An-Naḥl","sura_name_ar":"النَّحل ","line_start":"15","line_end":"15","aya_no":"128","aya_text":"إِنَّ ٱللَّهَ مَعَ ٱلَّذِينَ ٱتَّقَواْ وَّٱلَّذِينَ هُم مُّحۡسِنُونَ","aya_text_emlaey":"إن الله مع الذين اتقوا والذين هم محسنون","aya_tafseer":"[128] إن الله سبحانه وتعالى -بتوفيقه وعونه وتأييده ونصره- مع الذين اتقوه بامتثال ما أمر واجتناب ما نهى، ومع الذين يحسنون أداء فرائضه والقيام بحقوقه ولزوم طاعته."}]
